    async function goToOnboardingStep4() {
      const step3 = document.getElementById('womStep3');
      const step4 = document.getElementById('womStep4');
      const btn = document.getElementById('onbStep3ContinueBtn');
      if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>Activating Subscriptions... ⏳</span>';
      }

      // Gather checked starter channels and users
      const checkedBoxes = document.querySelectorAll('.onb-follow-cb:checked');
      const token = (myProfile && myProfile.sessionToken) || localStorage.getItem('sovra_session_token') || '';
      const headers = {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token,
        'bypass-tunnel-reminder': 'true'
      };

      const tasks = [];
      if (checkedBoxes && checkedBoxes.length > 0) {
        checkedBoxes.forEach(function(cb) {
          const type = cb.getAttribute('data-type');
          const id = cb.getAttribute('data-id');
          if (type === 'channel') {
            tasks.push(
              fetch('/api/social/channels/subscribe', {
                method: 'POST',
                headers: headers,
                body: JSON.stringify({ channelId: id, subscribe: true, sessionToken: token })
              }).catch(function() {})
            );
          } else if (type === 'user') {
            tasks.push(
              fetch('/api/social/follow', {
                method: 'POST',
                headers: headers,
                body: JSON.stringify({ targetDid: id, sessionToken: token })
              }).catch(function() {})
            );
          }
        });
      }

      if (tasks.length > 0) {
        try {
          await Promise.allSettled(tasks);
        } catch (_) {}
      }
      try {
        localStorage.setItem('sovra_has_followed', 'true');
      } catch (_) {}

      if (step3) step3.style.display = 'none';
      if (step4) step4.style.display = 'block';
    }

