    function updateOnboardingChecklistUI() {
      if (localStorage.getItem('sovra_checklist_dismissed') === 'true') {
        const checklist = document.getElementById('firstTimeUserChecklist');
        if (checklist) checklist.style.display = 'none';
        return;
      }

      const checklist = document.getElementById('firstTimeUserChecklist');
      if (!checklist) return;

      let completedCount = 0;
      const totalSteps = 4;

      // 1. Channel / Peer follow (defaults to complete if user followed starter pack or any creator/channel)
      let hasFollowed = false;
      try {
        hasFollowed = localStorage.getItem('sovra_has_followed') === 'true';
      } catch (_) {}
      if (!hasFollowed && typeof myProfile !== 'undefined' && myProfile) {
        if (Array.isArray(myProfile.followingDids) && myProfile.followingDids.length > 0) hasFollowed = true;
        if (Array.isArray(myProfile.subscribedChannels) && myProfile.subscribedChannels.length > 0) hasFollowed = true;
      }
      if (!hasFollowed && (localStorage.getItem('sovra_auth_mode') === 'registered' || localStorage.getItem('sovra_biometric_registered') === 'true')) {
        hasFollowed = true;
      }
      const t1Icon = document.getElementById('onbChecklistTask1Icon');
      if (hasFollowed) {
        completedCount++;
        if (t1Icon) t1Icon.innerText = '✅';
      } else {
        if (t1Icon) t1Icon.innerText = '⭕';
      }

      // 2. First post check
      let hasPosted = false;
      try {
        hasPosted = localStorage.getItem('sovra_has_posted') === 'true';
      } catch (_) {}
      if (!hasPosted && typeof feedPostsData !== 'undefined' && Array.isArray(feedPostsData) && typeof myProfile !== 'undefined' && myProfile && myProfile.did) {
        if (feedPostsData.some(function(p) { return p.authorDid === myProfile.did; })) {
          hasPosted = true;
          try { localStorage.setItem('sovra_has_posted', 'true'); } catch (_) {}
        }
      }
      const t2Icon = document.getElementById('onbChecklistTask2Icon');
      if (hasPosted) {
        completedCount++;
        if (t2Icon) t2Icon.innerText = '✅';
      } else {
        if (t2Icon) t2Icon.innerText = '⭕';
      }

      // 3. 50 SOV Balance in Vault
      completedCount++;
      const t3Icon = document.getElementById('onbChecklistTask3Icon');
      if (t3Icon) t3Icon.innerText = '✅';

      // 4. Encrypted Chat check
      let hasExploredChat = false;
      try {
        hasExploredChat = localStorage.getItem('sovra_explored_chat') === 'true';
      } catch (_) {}
      const t4Icon = document.getElementById('onbChecklistTask4Icon');
      if (hasExploredChat) {
        completedCount++;
        if (t4Icon) t4Icon.innerText = '✅';
      } else {
        if (t4Icon) t4Icon.innerText = '💬';
      }

      const pct = Math.round((completedCount / totalSteps) * 100);
      const progressBar = document.getElementById('onbChecklistProgressBar');
      const progressText = document.getElementById('onbChecklistProgressText');
      if (progressBar) progressBar.style.width = pct + '%';
      if (progressText) {
        progressText.innerText = completedCount === totalSteps
          ? '🎉 4 of 4 Completed (100%)'
          : (completedCount + ' of ' + totalSteps + ' Completed (' + pct + '%)');
      }

      checklist.style.display = 'block';
    }

    function formatBytes(bytes, decimals) {
      if (!bytes || bytes === 0) return '0 B';
      const k = 1024;
      const dm = (decimals === undefined || decimals < 0) ? 2 : decimals;
      const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
      const i = Math.floor(Math.log(bytes) / Math.log(k));
      return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
    }

    async function verifyCurrentIdentityCrypto(profile) {
      const badge = document.getElementById('meEd25519Badge');
      const checkmark = document.getElementById('meVerifiedCheckmark');
      const badgeBtn = document.getElementById('meVerifiedBadgeBtn');
      const cardBadge = document.getElementById('meCardCryptoBadge');
      if (badge) badge.innerText = 'Testing WebCrypto Enclave...';
      if (cardBadge) {
        cardBadge.innerText = 'Testing Enclave...';
        cardBadge.style.color = '#fbbf24';
        cardBadge.style.borderColor = 'rgba(245, 158, 11, 0.4)';
        cardBadge.style.background = 'rgba(245, 158, 11, 0.15)';
      }
      if (badgeBtn) {
        badgeBtn.style.borderColor = 'rgba(245, 158, 11, 0.4)';
        badgeBtn.style.color = '#f59e0b';
      }

      // Step 1: On-device WebCrypto Signature Self-Verification
      let localProof = null;
      if (window.SovraCryptoVault) {
        try {
          localProof = await window.SovraCryptoVault.testSignatureVerification('SOVRA_IDENTITY_VERIFY_' + Date.now());
        } catch(e) {}
      }

      if (localProof && localProof.ok) {
        if (badge) {
          badge.innerText = 'Verified';
        }
        if (cardBadge) {
          cardBadge.innerHTML = '✓ Biometric Enclave Verified';
          cardBadge.style.color = '#34d399';
          cardBadge.style.borderColor = 'rgba(52, 211, 153, 0.4)';
          cardBadge.style.background = 'rgba(16, 185, 129, 0.15)';
        }
        if (badgeBtn) {
          badgeBtn.title = 'Cryptographically Verified Sovereign DID — Hardware Protected';
          badgeBtn.style.borderColor = 'rgba(52, 211, 153, 0.4)';
          badgeBtn.style.color = '#34d399';
        }
        if (checkmark) checkmark.style.display = 'inline-block';
        if (profile) profile.isVerified = true;
        if (typeof showAccountToast === 'function') {
          showAccountToast('🛡️ Biometric Hardware Enclave Verified: Cryptographic signature verified', 'success');
        }
        return;
      }

      // Fallback: Query node verify API
      const did = (profile && profile.did) ? profile.did : '${masterKey.did}';
      fetch('/api/identity/verify?did=' + encodeURIComponent(did))
        .then(function(r) { return r.json(); })
        .then(function(res) {
          if (res && res.ok && res.verified) {
            if (badge) badge.innerText = 'Verified';
            if (cardBadge) {
              cardBadge.innerHTML = '✓ Node Verified';
              cardBadge.style.color = '#38bdf8';
              cardBadge.style.borderColor = 'rgba(56, 189, 248, 0.4)';
              cardBadge.style.background = 'rgba(56, 189, 248, 0.15)';
            }
            if (badgeBtn) {
              badgeBtn.style.borderColor = 'rgba(56, 189, 248, 0.35)';
              badgeBtn.style.color = '#38bdf8';
            }
            if (checkmark) checkmark.style.display = 'inline-block';
            if (profile) profile.isVerified = true;
          } else {
            if (badge) badge.innerText = 'Unverified DID';
            if (cardBadge) {
              cardBadge.innerText = '⚠ Unverified DID';
              cardBadge.style.color = '#ef4444';
              cardBadge.style.borderColor = 'rgba(239, 68, 68, 0.4)';
              cardBadge.style.background = 'rgba(239, 68, 68, 0.15)';
            }
            if (badgeBtn) {
              badgeBtn.style.borderColor = 'rgba(239, 68, 68, 0.4)';
              badgeBtn.style.color = '#ef4444';
            }
            if (checkmark) checkmark.style.display = 'none';
          }
        })
        .catch(function(err) {
          if (badge) badge.innerText = 'Ed25519 (Offline)';
          if (cardBadge) {
            cardBadge.innerText = 'Ed25519 (Offline)';
            cardBadge.style.color = '#94a3b8';
            cardBadge.style.borderColor = 'rgba(148, 163, 184, 0.3)';
          }
          if (badgeBtn) {
            badgeBtn.style.borderColor = 'rgba(148, 163, 184, 0.3)';
            badgeBtn.style.color = '#94a3b8';
          }
        });
    }

