    async function saveEditedProfile() {
      const nameInput = document.getElementById('editProfileNameInput');
      const handleInput = document.getElementById('editProfileHandleInput');
      const bioInput = document.getElementById('editProfileBioInput');
      const websiteInput = document.getElementById('editProfileWebsiteInput');

      const newName = (nameInput && nameInput.value.trim()) ? nameInput.value.trim() : (myProfile ? myProfile.name : 'Sovereign Node');
      let rawHandle = (handleInput && handleInput.value.trim()) ? handleInput.value.trim() : (myProfile ? myProfile.handle : '@user');
      if (!rawHandle.startsWith('@')) rawHandle = '@' + rawHandle;
      const newBio = bioInput ? bioInput.value.trim() : '';
      const newWebsite = (websiteInput && websiteInput.value.trim()) ? websiteInput.value.trim() : '';

      const token = localStorage.getItem('sovra_session_token') || (window.SOVRA_HOST_SESSION && window.SOVRA_HOST_SESSION.token) || (myProfile ? myProfile.sessionToken : '') || '';
      const updatedPayload = {
        did: myProfile ? myProfile.did : ('did:sovra:user_' + Math.random().toString(36).substring(2, 8)),
        sessionToken: token,
        handle: rawHandle,
        name: newName,
        displayName: newName,
        avatar: newName.charAt(0).toUpperCase(),
        avatarDataUrl: selectedEditAvatarDataUrl !== null ? selectedEditAvatarDataUrl : (myProfile ? (myProfile.avatarDataUrl || '') : ''),
        avatarBg: selectedEditAvatarBg,
        bio: newBio,
        website: newWebsite,
        coverDataUrl: selectedEditCoverDataUrl !== null ? selectedEditCoverDataUrl : (myProfile ? (myProfile.coverDataUrl || '') : ''),
        device: isMobileDevice ? 'Mobile' : 'Desktop'
      };

      try {
        const fetchFn = (typeof window.authenticatedFetch === 'function') ? window.authenticatedFetch : fetch;
        const res = await fetchFn('/api/user/update', {
          method: 'POST',
          headers: { 
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token
          },
          body: JSON.stringify(updatedPayload)
        });
        const data = await res.json();
        if (!res.ok || !data.ok) {
          alert('Could not update profile: ' + (data.error || 'Server error'));
          return;
        }

        myProfile = data.user;
        currentUserHandle = myProfile.handle;
        try {
          localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile));
          if (myProfile.sessionToken) localStorage.setItem('sovra_session_token', myProfile.sessionToken);
        } catch (e) {}

        fetch('/api/peers/register', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(myProfile)
        }).catch(function() {});

        updateUserDisplayInUI();
        closeEditProfileModal();
        showAccountToast('Profile saved to database and announced to peer mesh!');
      } catch (err) {
        alert('Network error while updating profile: ' + err);
      }
    }

    let womHandleCheckTimer = null;
    function validateWomHandleLive(rawHandle) {
      if (womHandleCheckTimer) clearTimeout(womHandleCheckTimer);
      const feedback = document.getElementById('womHandleFeedback');
      const errorBox = document.getElementById('womErrorMsg');
      if (errorBox) errorBox.style.display = 'none';
      if (!feedback) return;

      const trimmed = (rawHandle || '').trim().replace(/^@/, '');
      if (!trimmed) {
        feedback.innerText = 'Checked on P2P Mesh';
        feedback.style.color = '#94a3b8';
        return;
      }

      feedback.innerText = 'Checking...';
      feedback.style.color = '#38bdf8';

      womHandleCheckTimer = setTimeout(() => {
        fetch('/api/user/check-handle?handle=' + encodeURIComponent('@' + trimmed))
          .then(r => r.json())
          .then(data => {
            if (data.ok) {
              if (data.isAvailable) {
                feedback.innerText = '✓ Available';
                feedback.style.color = '#10b981';
              } else {
                feedback.innerText = '✕ Already Taken';
                feedback.style.color = '#f87171';
              }
            }
          })
          .catch(() => {
            feedback.innerText = 'Checked on P2P Mesh';
            feedback.style.color = '#94a3b8';
          });
      }, 250);
    }

    // Auto-check onboarding on first visit & restore session from server
    window.addEventListener('DOMContentLoaded', function() {
      if (!window.isSecureContext && window.location.protocol !== 'https:' && window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1') {
        var notice = document.getElementById('insecureContextNotice');
        if (notice) {
          notice.style.display = 'flex';
          var noticeLink = document.getElementById('insecureContextNoticeLink');
          if (noticeLink) {
            noticeLink.href = 'https://' + window.location.hostname + ':3443' + window.location.pathname;
          }
        }
      }

      const isExplicitlyLoggedOut = localStorage.getItem('sovra_logged_out') === 'true';
      const sessionToken = localStorage.getItem('sovra_session_token');
      const savedProfile = localStorage.getItem('sovra_user_profile');

      if (isExplicitlyLoggedOut || !sessionToken || !savedProfile) {
        updateUserDisplayInUI();
        showAuthLandingGate();
        return;
      }

      if (sessionToken) {
        const _meDidParam = (myProfile && myProfile.did) ? ('&did=' + encodeURIComponent(myProfile.did)) : '';
        const _meHandleParam = (myProfile && myProfile.handle) ? ('&handle=' + encodeURIComponent(myProfile.handle)) : '';
        fetch('/api/user/me?sessionToken=' + encodeURIComponent(sessionToken) + _meDidParam + _meHandleParam)
          .then(r => r.json())
          .then(data => {
            if (data.ok && data.user) {
              myProfile = data.user;
              currentUserHandle = myProfile.handle;
              try { localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile)); } catch(e) {}
              updateUserDisplayInUI();
              if (typeof fetchNotifications === 'function') fetchNotifications();
              if (typeof syncFriendsRelationships === 'function') syncFriendsRelationships();
              if (typeof syncPeersAndContacts === 'function') syncPeersAndContacts();
              if (typeof fetchAndRenderStories === 'function') fetchAndRenderStories();
              // Register heartbeat with server
              fetch('/api/peers/register', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(myProfile)
              }).catch(function() {});
            } else {
              myProfile = null;
              currentUserHandle = '@guest';
              localStorage.removeItem('sovra_user_profile');
              localStorage.removeItem('sovra_session_token');
              updateUserDisplayInUI();
              showAuthLandingGate();
            }
          })
          .catch(() => {
            if (myProfile) updateUserDisplayInUI();
            else showAuthLandingGate();
          });
      } else {
        updateUserDisplayInUI();
        showAuthLandingGate();
      }

      if (!isSovraAppInstalled()) {
        setTimeout(function() {
          if (isSovraAppInstalled()) return;
          const banner = document.getElementById('pwaInstallBanner');
          if (banner) {
            banner.style.display = 'flex';
          }
          const topBtn = document.getElementById('pwaInstallBtn');
          if (topBtn) topBtn.style.display = 'inline-flex';
        }, 800);
      }
      setTimeout(function() {
        if (typeof syncFriendsRelationships === 'function') syncFriendsRelationships();
        if (typeof renderRightRailSuggestions === 'function') renderRightRailSuggestions();
        if (typeof renderFbContacts === 'function') renderFbContacts();
        if (typeof renderTrendingHashtags === 'function') renderTrendingHashtags();
        if (typeof updateProfileDynamicStats === 'function') updateProfileDynamicStats();
      }, 400);
      setInterval(function() {
        if (typeof updateProfileDynamicStats === 'function') updateProfileDynamicStats();
      }, 5000);
      setInterval(function() {
        if (typeof renderTrendingHashtags === 'function') renderTrendingHashtags();
      }, 30000);
    });

