    async function generateEncryptedVaultBundle() {
      clearVaultNotice();
      var p1 = document.getElementById('vaultExportPassphrase');
      var p2 = document.getElementById('vaultExportPassphraseConfirm');
      var pass = p1 ? p1.value : '';
      var confirm = p2 ? p2.value : '';

      if (!pass || pass.length < 6) {
        showVaultNotice('⚠️ Passphrase must be at least 6 characters long.', false);
        return;
      }
      if (pass !== confirm) {
        showVaultNotice('⚠️ Passphrase and confirmation do not match.', false);
        return;
      }

      var btn = document.getElementById('btnGenerateVaultBackup');
      if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>🔒 Encrypting Vault with PBKDF2...</span>';
      }

      try {
        if (!window.SovraCryptoVault) {
          throw new Error('Sovereign Crypto Vault is not initialized in this environment.');
        }
        var bundle = await window.SovraCryptoVault.exportEncryptedVault(pass);
        _lastExportedVaultBundle = bundle;

        var resultArea = document.getElementById('vaultExportResultArea');
        if (resultArea) resultArea.style.display = 'block';

        var preview = document.getElementById('vaultExportJsonPreview');
        if (preview) {
          preview.innerText = JSON.stringify(bundle, null, 2);
        }

        showVaultNotice('✅ Vault encrypted successfully with AES-256-GCM + PBKDF2 (100k rounds)!', true);
        if (typeof showAccountToast === 'function') {
          showAccountToast('🔐 Sovereign Key Vault backup bundle generated!', 'success');
        }
      } catch (err) {
        showVaultNotice('Encryption failure: ' + (err.message || err), false);
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.innerHTML = '<span>🔒 Generate Encrypted Vault</span>';
        }
      }
    }

    function downloadVaultBundle() {
      if (!_lastExportedVaultBundle) {
        showVaultNotice('Please generate the encrypted vault first.', false);
        return;
      }
      try {
        var str = JSON.stringify(_lastExportedVaultBundle, null, 2);
        var blob = new Blob([str], { type: 'application/json' });
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a');
        var filename = 'sovra-vault-' + (_lastExportedVaultBundle.did ? _lastExportedVaultBundle.did.slice(-8) : Date.now()) + '.sovra-vault.json';
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        if (typeof showAccountToast === 'function') {
          showAccountToast('📥 Downloaded ' + filename, 'success');
        }
      } catch (err) {
        showVaultNotice('Failed to download vault file: ' + (err.message || err), false);
      }
    }

    function copyVaultBundle() {
      if (!_lastExportedVaultBundle) {
        showVaultNotice('Please generate the encrypted vault first.', false);
        return;
      }
      var str = JSON.stringify(_lastExportedVaultBundle, null, 2);
      copyToClipboard(str, function(success) {
        if (success) {
          showVaultNotice('📋 Encrypted JSON bundle copied to clipboard!', true);
          if (typeof showAccountToast === 'function') {
            showAccountToast('📋 Encrypted vault JSON copied!');
          }
        } else {
          prompt('Copy Encrypted Vault JSON:', str);
        }
      });
    }

    function handleVaultFileUpload(event) {
      clearVaultNotice();
      var input = event.target;
      if (!input || !input.files || !input.files[0]) return;
      var file = input.files[0];
      var reader = new FileReader();
      reader.onload = function(e) {
        try {
          var text = e.target.result;
          var jsonInput = document.getElementById('vaultImportJsonInput');
          if (jsonInput) jsonInput.value = text;
          showVaultNotice('📁 ' + file.name + ' loaded into restore buffer. Enter passphrase to decrypt.', true);
        } catch (err) {
          showVaultNotice('Failed to read file: ' + (err.message || err), false);
        }
      };
      reader.onerror = function() {
        showVaultNotice('Failed reading uploaded file.', false);
      };
      reader.readAsText(file);
    }

    async function restoreEncryptedVaultBundle() {
      clearVaultNotice();
      var jsonInput = document.getElementById('vaultImportJsonInput');
      var passInput = document.getElementById('vaultImportPassphrase');
      var rawJson = jsonInput ? jsonInput.value.trim() : '';
      var pass = passInput ? passInput.value : '';

      if (!rawJson) {
        showVaultNotice('⚠️ Please load or paste a valid encrypted vault JSON bundle.', false);
        return;
      }
      if (!pass) {
        showVaultNotice('⚠️ Decryption passphrase is required.', false);
        return;
      }

      var bundle;
      try {
        bundle = JSON.parse(rawJson);
      } catch (e) {
        showVaultNotice('⚠️ Invalid JSON format in restore buffer.', false);
        return;
      }

      var btn = document.getElementById('btnRestoreVaultBackup');
      if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>⚡ Decrypting & Restoring Sovereign Keys...</span>';
      }

      try {
        if (!window.SovraCryptoVault) {
          throw new Error('Sovereign Crypto Vault is not initialized in this environment.');
        }
        var res = await window.SovraCryptoVault.importEncryptedVault(bundle, pass);
        if (res && res.ok) {
          showVaultNotice('✅ Sovereign Keys successfully restored into IndexedDB enclave! DID: ' + (res.did || bundle.did), true);
          if (typeof showAccountToast === 'function') {
            showAccountToast('⚡ Sovereign Key Vault restored into local enclave!', 'success');
          }
          if (res.did && myProfile) {
            myProfile.did = res.did;
            try { localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile)); } catch(e) {}
          }
        } else {
          throw new Error('Restoration failed.');
        }
      } catch (err) {
        showVaultNotice('❌ Decryption failed: ' + (err.message || 'Incorrect passphrase or corrupted bundle.'), false);
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.innerHTML = '<span>⚡ Decrypt & Restore Sovereign Keys</span>';
        }
      }
    }

    async function renderVaultMnemonic() {
      var grid = document.getElementById('vaultMnemonicWordsGrid');
      if (!grid) return;
      var words = [];
      if (window.SovraCryptoVault && typeof window.SovraCryptoVault.getMnemonicWords === 'function') {
        try {
          words = await window.SovraCryptoVault.getMnemonicWords();
        } catch (e) {}
      }
      if (!words || words.length < 12) {
        var seed = (myProfile && (myProfile.did || myProfile.handle)) || 'sovra_' + Date.now();
        var fallbackStr = generateClientDeterministicPhrase(seed);
        words = fallbackStr.split(' ');
      }
      var html = '';
      for (var i = 0; i < words.length; i++) {
        html += '<div style="background: rgba(168, 85, 247, 0.08); padding: 8px 10px; border-radius: 8px; border: 1px solid rgba(168, 85, 247, 0.2); display: flex; align-items: center; gap: 6px; min-width: 0; overflow: hidden;">' +
          '<span style="font-size: 0.7rem; color: #a855f7; font-weight: 800; width: 18px; flex-shrink: 0;">' + (i + 1) + '.</span>' +
          '<span style="font-size: 0.82rem; font-family: monospace; color: #e9d5ff; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">' + words[i] + '</span>' +
          '</div>';
      }
      grid.innerHTML = html;
    }

