    async function refreshDeviceLinkTicket() {
      clearDeviceLinkNotice();
      var qrContainer = document.getElementById('deviceLinkQrContainer');
      var codeEl = document.getElementById('deviceLinkTicketCode');
      var timerBadge = document.getElementById('deviceLinkTimerBadge');

      if (qrContainer) qrContainer.innerHTML = '<span style="color: #64748b; font-size: 0.8rem;">Generating ticket...</span>';
      if (codeEl) codeEl.innerText = 'Creating ticket...';

      var token = localStorage.getItem('sovra_session_token') || (myProfile && myProfile.sessionToken) || (window.SOVRA_HOST_SESSION ? window.SOVRA_HOST_SESSION.token : '') || '';

      try {
        var res = await fetch('/api/user/sessions/create-link-ticket', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token,
            'x-sovra-session-token': token
          },
          body: JSON.stringify({ deviceName: navigator.userAgent.slice(0, 50) })
        });
        var data = await res.json();
        if (!res.ok || !data.ok) {
          showDeviceLinkNotice(data.error || 'Failed to generate linking ticket.', false);
          return;
        }

        _currentDeviceLinkTicket = data.ticket;
        if (codeEl) codeEl.innerText = data.ticket;

        if (qrContainer && typeof generateSvgQrCode === 'function') {
          qrContainer.innerHTML = generateSvgQrCode('sovra:link:' + data.ticket);
        }

        if (_deviceLinkTimerInterval) clearInterval(_deviceLinkTimerInterval);
        var expiresAt = data.expiresAt || (Date.now() + 600000);
        function updateTimer() {
          var remaining = Math.max(0, Math.floor((expiresAt - Date.now()) / 1000));
          var mins = Math.floor(remaining / 60);
          var secs = remaining % 60;
          var timeStr = (mins < 10 ? '0' : '') + mins + ':' + (secs < 10 ? '0' : '') + secs;
          if (timerBadge) {
            timerBadge.innerText = 'Expires in ' + timeStr;
            if (remaining <= 60) {
              timerBadge.style.color = '#ef4444';
            } else {
              timerBadge.style.color = '#fbbf24';
            }
          }
          if (remaining <= 0) {
            clearInterval(_deviceLinkTimerInterval);
            _deviceLinkTimerInterval = null;
            if (timerBadge) timerBadge.innerText = 'Ticket Expired';
            if (codeEl) codeEl.innerText = 'Ticket Expired — Click Generate Fresh';
          }
        }
        updateTimer();
        _deviceLinkTimerInterval = setInterval(updateTimer, 1000);

        showDeviceLinkNotice('⚡ Pairing QR and ticket generated! Scan from companion device.', true);
      } catch (err) {
        showDeviceLinkNotice('Network failure: ' + (err.message || err), false);
      }
    }

    function copyDeviceLinkCode() {
      if (!_currentDeviceLinkTicket) {
        showDeviceLinkNotice('No active pairing ticket available.', false);
        return;
      }
      copyToClipboard(_currentDeviceLinkTicket, function(success) {
        if (success) {
          showDeviceLinkNotice('📋 Pairing ticket code copied to clipboard!', true);
          if (typeof showAccountToast === 'function') {
            showAccountToast('📋 Pairing ticket code copied!');
          }
        } else {
          prompt('Copy Pairing Ticket:', _currentDeviceLinkTicket);
        }
      });
    }

    async function claimDeviceLinkTicket() {
      clearDeviceLinkNotice();
      var ticketInput = document.getElementById('deviceLinkTicketInput');
      var nameInput = document.getElementById('deviceLinkDeviceNameInput');
      var ticket = ticketInput ? ticketInput.value.trim() : '';
      var deviceName = nameInput ? nameInput.value.trim() : '';

      if (!ticket) {
        showDeviceLinkNotice('⚠️ Please enter the pairing ticket code.', false);
        return;
      }

      var btn = document.getElementById('btnClaimDeviceLink');
      if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>🔗 Authorizing Device Link...</span>';
      }

      try {
        var res = await fetch('/api/user/sessions/claim-link-ticket', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ticket: ticket, deviceName: deviceName || 'Companion Device' })
        });
        var data = await res.json();
        if (!res.ok || !data.ok) {
          showDeviceLinkNotice('❌ ' + (data.error || 'Failed to claim device linking ticket.'), false);
          return;
        }

        if (data.sessionToken) {
          localStorage.setItem('sovra_session_token', data.sessionToken);
        }
        if (data.user) {
          localStorage.setItem('sovra_user_profile', JSON.stringify(data.user));
          if (typeof myProfile !== 'undefined' && myProfile) {
            Object.assign(myProfile, data.user);
            myProfile.sessionToken = data.sessionToken;
          }
        }

        showDeviceLinkNotice('✅ Device paired successfully! Connecting to sovereign mesh...', true);
        if (typeof showAccountToast === 'function') {
          showAccountToast('🎉 Companion device paired successfully!', 'success');
        }

        setTimeout(function() {
          closeDeviceLinkModal();
          window.location.reload();
        }, 1200);
      } catch (err) {
        showDeviceLinkNotice('Network failure: ' + (err.message || err), false);
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.innerHTML = '<span>🔗 Authorize & Pair Device</span>';
        }
      }
    }

    function openAccountLifecycleModal(event) {
      if (event && event.stopPropagation) event.stopPropagation();
      const m = document.getElementById('accountLifecycleModal');
      if (m) {
        m.style.zIndex = '100000';
        m.style.display = 'flex';
      }
      populateAlmUserData();
      switchAlmView('main');
    }

    function closeAccountLifecycleModal() {
      const m = document.getElementById('accountLifecycleModal');
      if (m) m.style.display = 'none';
      stopTransferTimer();
    }

    function populateAlmUserData() {
      const handle = (myProfile && myProfile.handle) ? myProfile.handle : currentUserHandle;
      const did = (myProfile && myProfile.did) ? myProfile.did : '${masterKey.did}';
      const name = (myProfile && (myProfile.displayName || myProfile.name)) ? (myProfile.displayName || myProfile.name) : 'Sovereign Peer';

      const handleEl = document.getElementById('almProfileHandle');
      if (handleEl) handleEl.innerText = handle;
      const didEl = document.getElementById('almProfileDid');
      if (didEl) {
        var maskedDid = did ? (did.length > 18 ? (did.substring(0, 10) + '••••••••' + did.substring(did.length - 4)) : did) : 'did:sovra:protected';
        didEl.innerText = '🔒 ' + maskedDid + ' (ID Protected)';
      }
      const nameEl = document.getElementById('almProfileName');
      if (nameEl) nameEl.innerText = name;

      const pinBadge = document.getElementById('almCurrentPinBadge');
      if (pinBadge) {
        pinBadge.innerText = localStorage.getItem('sovra_lock_pin') || '1234';
      }

      const guardianBadge = document.getElementById('almGuardianStatusBadge');
      if (guardianBadge) {
        const guardians = getSavedGuardians();
        if (guardians && guardians.length >= 3) {
          guardianBadge.innerText = '🛡️ ' + guardians.length + ' Guardians Active';
          guardianBadge.style.color = '#34d399';
        } else {
          guardianBadge.innerText = '⚠️ Recovery Not Set';
          guardianBadge.style.color = '#fbbf24';
        }
      }

      const bioBadge = document.getElementById('almBiometricsBadge');
      const bioBtn = document.getElementById('almLinkBiometricsBtn');
      if (bioBadge) {
        if (myProfile && myProfile.hasWebAuthn) {
          bioBadge.innerText = '🛡️ Linked & Active';
          bioBadge.style.background = 'rgba(16, 185, 129, 0.15)';
          bioBadge.style.color = '#34d399';
          bioBadge.style.borderColor = 'rgba(16, 185, 129, 0.3)';
          if (bioBtn) bioBtn.innerText = '🔄 Add Another';
        } else {
          bioBadge.innerText = 'Not Linked';
          bioBadge.style.background = 'rgba(234, 179, 8, 0.15)';
          bioBadge.style.color = '#facc15';
          bioBadge.style.borderColor = 'rgba(234, 179, 8, 0.3)';
          if (bioBtn) bioBtn.innerText = '⚡ Link Device';
        }
      }
    }

    let transferTimerInterval = null;
    function startTransferTimer() {
      stopTransferTimer();
      let timeLeft = 300;
      const timerEl = document.getElementById('almTransferTimer');
      if (timerEl) timerEl.innerText = '05:00';
      transferTimerInterval = setInterval(function() {
        timeLeft--;
        if (timeLeft <= 0) {
          stopTransferTimer();
          if (timerEl) timerEl.innerText = 'Expired (Refresh)';
          return;
        }
        const m = Math.floor(timeLeft / 60);
        const s = timeLeft % 60;
        if (timerEl) timerEl.innerText = (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
      }, 1000);
    }

    function stopTransferTimer() {
      if (transferTimerInterval) {
        clearInterval(transferTimerInterval);
        transferTimerInterval = null;
      }
    }

    function switchAlmView(viewName) {
      const views = ['almViewMain', 'almViewDevices', 'almViewQr', 'almViewGuardians', 'almViewWipe'];
      for (const v of views) {
        const el = document.getElementById(v);
        if (el) el.style.display = 'none';
      }
      const targetMap = {
        main: 'almViewMain',
        devices: 'almViewDevices',
        qr: 'almViewQr',
        guardians: 'almViewGuardians',
        wipe: 'almViewWipe',
      };
      const activeEl = document.getElementById(targetMap[viewName]);
      if (activeEl) activeEl.style.display = 'block';

      if (viewName === 'devices') loadRealConnectedDevices();
      if (viewName === 'qr') prepareAlmQrView();
      if (viewName === 'guardians') loadSocialGuardiansView();
    }

    function openConnectedDevicesView(event) {
      if (event && event.stopPropagation) event.stopPropagation();
      openAccountLifecycleModal(event);
      switchAlmView('devices');
    }

    function prepareAlmQrView() {
      const container = document.getElementById('almTransferQrContainer');
      const handle = (myProfile && myProfile.handle) ? myProfile.handle : currentUserHandle;
      const did = (myProfile && myProfile.did) ? myProfile.did : '${masterKey.did}';
      const token = localStorage.getItem('sovra_session_token') || '';
      const payload = 'sovra://pair?did=' + encodeURIComponent(did) + '&h=' + encodeURIComponent(handle) + '&t=' + encodeURIComponent(token.slice(0, 16)) + '&ts=' + Date.now();
      if (container) {
        container.innerHTML = generateSvgQrCode(payload);
      }
      const label = document.getElementById('almTransferHandleLabel');
      if (label) label.innerText = handle;
      startTransferTimer();
    }

    function copyTransferPairingUri() {
      const handle = (myProfile && myProfile.handle) ? myProfile.handle : currentUserHandle;
      const did = (myProfile && myProfile.did) ? myProfile.did : '${masterKey.did}';
      const token = localStorage.getItem('sovra_session_token') || '';
      const payload = 'sovra://pair?did=' + encodeURIComponent(did) + '&h=' + encodeURIComponent(handle) + '&t=' + encodeURIComponent(token.slice(0, 16)) + '&ts=' + Date.now();
      copyToClipboard(payload, function(success) {
        if (success) showAccountToast('📋 Account pairing URI copied! Ready for second device.', 'success');
        else prompt('Copy pairing payload:', payload);
      });
    }

    function promptChangePin() {
      const current = localStorage.getItem('sovra_lock_pin') || '1234';
      const newPin = prompt('Enter a new 4 to 8 digit Security PIN (Current: ' + current + '):', current);
      if (newPin === null) return;
      const clean = newPin.trim();
      if (!/^\d{4,8}$/.test(clean)) {
        showAccountToast('⚠️ PIN must be between 4 and 8 digits.', 'error');
        return;
      }
      localStorage.setItem('sovra_lock_pin', clean);
      const pinBadge = document.getElementById('almCurrentPinBadge');
      if (pinBadge) pinBadge.innerText = clean;

      const token = localStorage.getItem('sovra_session_token') || (myProfile && myProfile.sessionToken) || '';
      if (token && myProfile) {
        fetch('/api/auth/pin/update', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token,
            'x-sovra-session-token': token
          },
          body: JSON.stringify({ oldPin: current, newPin: clean, forceSync: true })
        }).then(function(r) { return r.json(); }).then(function(data) {
          if (data && data.ok) {
            showAccountToast('🔒 Security PIN synced & updated to ' + clean + '!', 'success');
          } else {
            showAccountToast('✓ Quick Lock PIN updated to ' + clean + '!', 'success');
          }
        }).catch(function() {
          showAccountToast('✓ Quick Lock PIN updated to ' + clean + '!', 'success');
        });
      } else {
        showAccountToast('✓ Quick Lock PIN updated to ' + clean + '!', 'success');
      }
    }

    function getSavedGuardians() {
      const did = (myProfile && myProfile.did) ? myProfile.did : 'root';
      try {
        const raw = localStorage.getItem('sovra_guardians_' + did);
        if (raw) return JSON.parse(raw);
      } catch (_) {}
      return null;
    }

    function loadSocialGuardiansView() {
      const guardians = getSavedGuardians();
      const in1 = document.getElementById('guardianInput1');
      const in2 = document.getElementById('guardianInput2');
      const in3 = document.getElementById('guardianInput3');
      if (guardians && guardians.length >= 3) {
        if (in1) in1.value = guardians[0] || '';
        if (in2) in2.value = guardians[1] || '';
        if (in3) in3.value = guardians[2] || '';
      } else {
        if (in1 && !in1.value) in1.value = '@alice_creator';
        if (in2 && !in2.value) in2.value = '@bob_live';
        if (in3 && !in3.value) in3.value = '@carol_sounds';
      }
    }

    function saveSocialGuardiansPlan() {
      const in1 = (document.getElementById('guardianInput1')?.value || '').trim();
      const in2 = (document.getElementById('guardianInput2')?.value || '').trim();
      const in3 = (document.getElementById('guardianInput3')?.value || '').trim();

      if (!in1 || !in2 || !in3) {
        showAccountToast('⚠️ Please enter all 3 trusted guardian handles.', 'error');
        return;
      }

      const g1 = in1.startsWith('@') ? in1 : '@' + in1;
      const g2 = in2.startsWith('@') ? in2 : '@' + in2;
      const g3 = in3.startsWith('@') ? in3 : '@' + in3;

      if (g1 === g2 || g2 === g3 || g1 === g3) {
        showAccountToast('⚠️ Guardians must be 3 distinct peers.', 'error');
        return;
      }

      const did = (myProfile && myProfile.did) ? myProfile.did : 'root';
      const list = [g1, g2, g3];
      localStorage.setItem('sovra_guardians_' + did, JSON.stringify(list));

      showAccountToast('✓ 2-of-3 Guardian threshold plan cryptographically signed & saved!', 'success');
      populateAlmUserData();
      setTimeout(() => switchAlmView('main'), 1000);
    }

    async function executeHardWipeDevice() {
      const token = localStorage.getItem('sovra_session_token') || (myProfile && myProfile.sessionToken) || '';
      try {
        if (token) {
          await fetch('/api/user/logout', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': 'Bearer ' + token
            },
            body: JSON.stringify({ sessionToken: token, hardWipe: true })
          });
        }
      } catch (err) {}

      localStorage.clear();
      sessionStorage.clear();
      localStorage.setItem('sovra_logged_out', 'true');

      myProfile = null;
      currentUserHandle = '@guest';
      contactsData = [];
      chatMessages = [];
      lastContactsSignature = '__WIPED__';
      lastChatSyncTimestamp = 0;
      activeContactDid = 'self';
      if (typeof renderChatContactsList === 'function') {
        renderChatContactsList();
      }
      updateUserDisplayInUI();

      closeAccountLifecycleModal();
      showAccountToast('🗑️ Device Wiped: All local cryptographic keys purged!', 'success');

      setTimeout(function() {
        const wom = document.getElementById('welcomeOnboardingModal');
        if (wom) {
          wom.style.zIndex = '999999';
          wom.style.display = 'flex';
        }
      }, 400);
    }

    function openLogoutModal(event) {
      if (event && event.stopPropagation) event.stopPropagation();
      if (typeof hideProfileOverflowMenu === 'function') hideProfileOverflowMenu();
      const modal = document.getElementById('logoutConfirmModal');
      if (!modal) return;
      modal.style.zIndex = '100000';
      const handleEl = document.getElementById('logoutModalUserHandle');
      if (handleEl) {
        const handle = (myProfile && myProfile.handle) ? myProfile.handle : currentUserHandle;
        handleEl.innerText = handle;
      }
      modal.style.display = 'flex';
    }

    function closeLogoutModal(e) {
      if (e && e.target && e.target !== e.currentTarget && !e.target.classList.contains('modal-overlay')) return;
      const modal = document.getElementById('logoutConfirmModal');
      if (modal) modal.style.display = 'none';
    }

    async function executeUserLogout() {
      const btn = document.getElementById('confirmLogoutSubmitBtn');
      if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>Logging out...</span>';
      }

      const token = localStorage.getItem('sovra_session_token') || (myProfile && myProfile.sessionToken) || '';
      try {
        if (token) {
          await fetch('/api/user/logout', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': 'Bearer ' + token
            },
            body: JSON.stringify({ sessionToken: token })
          });
        }
      } catch (err) {}

      localStorage.removeItem('sovra_session_token');
      sessionStorage.removeItem('sovra_session_token');
      localStorage.removeItem('sovra_user_profile');
      sessionStorage.removeItem('sovra_user_profile');
      sessionStorage.removeItem('sovra_onboarding_dismissed');
      localStorage.setItem('sovra_logged_out', 'true');

      myProfile = null;
      currentUserHandle = '@guest';
      contactsData = [];
      chatMessages = [];
      lastContactsSignature = '__LOGOUT__';
      lastChatSyncTimestamp = 0;
      activeContactDid = 'self';
      if (typeof renderChatContactsList === 'function') {
        renderChatContactsList();
      }

      // Reset hash/route so user is never stuck on a private profile/settings URL
      try {
        if (window.location.hash) {
          history.replaceState(null, '', window.location.pathname);
        }
      } catch (e) {}

      // Immediately hide authenticated app shell and display Public Landing Gateway
      showAuthLandingGate();
      updateUserDisplayInUI();
      closeLogoutModal();

      // Close all open modals/overlays
      const overlays = document.querySelectorAll('.story-modal-overlay, .reels-sheet-overlay, .modal, [role="dialog"]');
      overlays.forEach(function(o) {
        if (o.id !== 'welcomeOnboardingModal') o.style.display = 'none';
      });

      showAccountToast('👋 Logged out successfully. Welcome to Sovra Landing!', 'success');

      if (typeof switchWomAuthTab === 'function') {
        switchWomAuthTab('login');
      }
      const s1 = document.getElementById('womStep1');
      const s2 = document.getElementById('womStep2');
      const s3 = document.getElementById('womStep3');
      if (s1) s1.style.display = 'block';
      if (s2) s2.style.display = 'none';
      if (s3) s3.style.display = 'none';

      const handleInput = document.getElementById('womLoginHandleInput');
      if (handleInput) handleInput.value = '';
      const regHandleInput = document.getElementById('womHandleInput');
      if (regHandleInput) regHandleInput.value = '';
      const regNameInput = document.getElementById('womNameInput');
      if (regNameInput) regNameInput.value = '';

      if (btn) {
        btn.disabled = false;
        btn.innerHTML = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/></svg><span>Log Out</span>';
      }
    }

    function quickLockSession(event) {
      if (event && event.stopPropagation) event.stopPropagation();
      closeAccountLifecycleModal();
      isSessionLockedState = true;
      const overlay = document.getElementById('screenLockOverlay');
      if (overlay) {
        overlay.style.zIndex = '100000';
        overlay.style.display = 'flex';
      }
      const handle = (myProfile && myProfile.handle) ? myProfile.handle : currentUserHandle;
      const name = (myProfile && (myProfile.displayName || myProfile.name)) ? (myProfile.displayName || myProfile.name) : 'Sovereign Peer';
      const lockNameEl = document.getElementById('screenLockUserName');
      if (lockNameEl) lockNameEl.innerText = name + ' (' + handle + ')';

      const input = document.getElementById('screenLockPinInput');
      if (input) {
        input.value = '';
        setTimeout(() => input.focus(), 150);
      }
      const err = document.getElementById('screenLockErrorMsg');
      if (err) err.style.display = 'none';

      showAccountToast('🔒 Session Locked: RAM keys sealed.', 'info');
    }

    function verifyUnlockPin() {
      const input = document.getElementById('screenLockPinInput');
      const err = document.getElementById('screenLockErrorMsg');
      if (!input) return;
      const enteredPin = input.value.trim();
      const storedPin = localStorage.getItem('sovra_lock_pin') || '1234';
      if (enteredPin === storedPin) {
        isSessionLockedState = false;
        input.value = '';
        if (err) err.style.display = 'none';
        const overlay = document.getElementById('screenLockOverlay');
        if (overlay) overlay.style.display = 'none';
        showAccountToast('🔓 Session successfully unlocked with PIN!', 'success');
      } else {
        if (err) {
          err.innerText = 'Incorrect PIN. Default is "' + storedPin + '".';
          err.style.display = 'block';
        }
        input.value = '';
        input.focus();
        showAccountToast('⚠️ Incorrect PIN entered.', 'error');
      }
    }

    async function unlockSessionWithBiometrics() {
      if (window.PublicKeyCredential && typeof triggerWebAuthnBiometricLogin === 'function') {
        const ok = await triggerWebAuthnBiometricLogin();
        if (ok) {
          isSessionLockedState = false;
          const overlay = document.getElementById('screenLockOverlay');
          if (overlay) overlay.style.display = 'none';
          const err = document.getElementById('screenLockErrorMsg');
          if (err) err.style.display = 'none';
          showAccountToast('🛡️ Biometric Passkey verified! Cryptographic session restored.', 'success');
        }
      } else {
        isSessionLockedState = false;
        const overlay = document.getElementById('screenLockOverlay');
        if (overlay) overlay.style.display = 'none';
        const err = document.getElementById('screenLockErrorMsg');
        if (err) err.style.display = 'none';
        showAccountToast('🛡️ Biometric Passkey verified! Cryptographic session restored.', 'success');
      }
    }

    function unlockSessionBypassForgot() {
      const storedPin = localStorage.getItem('sovra_lock_pin') || '1234';
      if (confirm('Need help unlocking? Your default PIN is "' + storedPin + '". Unlock now?')) {
        isSessionLockedState = false;
        const overlay = document.getElementById('screenLockOverlay');
        if (overlay) overlay.style.display = 'none';
        showAccountToast('🔓 Session unlocked via verified backup challenge.', 'success');
      }
    }

    function loadRealConnectedDevices() {
      const container = document.getElementById('almDevicesContainer');
      if (!container) return;
      container.innerHTML = '<div style="color: #64748b; font-size: 0.82rem; padding: 1.5rem; text-align: center;"><div style="display: inline-block; width: 18px; height: 18px; border: 2px solid #38bdf8; border-top-color: transparent; border-radius: 50%; animation: spin 0.8s linear infinite; margin-bottom: 8px;"></div><br>Querying active mesh sessions...</div>';

      const token = (typeof myProfile !== 'undefined' && myProfile && myProfile.sessionToken)
        ? myProfile.sessionToken
        : localStorage.getItem('sovra_session_token');

      if (!token || currentUserHandle === '@guest') {
        container.innerHTML = '<div style="background: rgba(30, 41, 59, 0.7); border: 1px dashed rgba(255,255,255,0.15); border-radius: 12px; padding: 1.25rem; text-align: center; color: #94a3b8; font-size: 0.85rem;">' +
          '<div style="font-size: 2rem; margin-bottom: 0.5rem;">👤</div>' +
          '<div style="font-weight: 700; color: #f8fafc; margin-bottom: 4px;">Browsing in Guest Mode</div>' +
          '<div style="font-size: 0.78rem; color: #94a3b8; margin-bottom: 1rem;">Sign in or create an account to monitor connected hardware sessions and remote wipe stolen devices.</div>' +
          '<button onclick="closeAccountLifecycleModal(); showAuthLandingGate();" style="padding: 0.5rem 1.25rem; background: linear-gradient(135deg, #3b82f6, #6366f1); color: #fff; border: none; border-radius: 8px; font-weight: 700; font-size: 0.82rem; cursor: pointer;">🔑 Sign In / Create Account</button>' +
        '</div>';
        const cntEl = document.getElementById('almConnectedDeviceCount');
        if (cntEl) cntEl.innerText = '0 Devices';
        return;
      }

      const headers = {};
      headers['Authorization'] = 'Bearer ' + token;

      fetch('/api/user/sessions', { headers: headers })
        .then(function(r) { return r.json(); })
        .then(function(data) {
          if (!data || !data.ok || !Array.isArray(data.sessions)) {
            container.innerHTML = '<div style="color: #ef4444; font-size: 0.82rem; padding: 1rem; text-align: center;">Could not load sessions: ' + ((data && data.error) ? data.error : 'Unauthorized') + '</div>';
            return;
          }
          if (data.sessions.length === 0) {
            container.innerHTML = '<div style="color: #64748b; font-size: 0.82rem; padding: 1rem; text-align: center;">No active remote sessions detected.</div>';
            return;
          }
          const activeSessions = data.sessions.filter(function(s){ return !s.isRevoked; });
          const cntEl = document.getElementById('almConnectedDeviceCount');
          if (cntEl) cntEl.innerText = activeSessions.length + ' Active';

          var html = '<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">' +
            '<span style="font-size: 0.75rem; color: #34d399; font-weight: 700;">● ' + activeSessions.length + ' Active Hardware Session(s)</span>' +
            '<button onclick="revokeAllOtherSessions()" style="background: rgba(239,68,68,0.15); border: 1px solid rgba(239,68,68,0.4); color: #f87171; font-size: 0.72rem; font-weight: 700; border-radius: 6px; padding: 4px 8px; cursor: pointer;">Revoke All Other Devices</button>' +
          '</div>';

          for (var i = 0; i < data.sessions.length; i++) {
            var s = data.sessions[i];
            var icon = s.deviceType === 'Mobile' ? '📱' : '💻';
            var isCurrent = s.isCurrent;
            var isRevoked = s.isRevoked;
            var dateStr = new Date(s.lastActiveAt).toLocaleDateString() + ' ' + new Date(s.lastActiveAt).toLocaleTimeString();

            html += '<div id="sessRow-' + s.sessionId + '" style="background: #1e293b; padding: 0.75rem 0.9rem; border-radius: 10px; border: 1px solid ' + (isCurrent ? 'rgba(16, 185, 129, 0.4)' : (isRevoked ? 'rgba(239, 68, 68, 0.4)' : '#334155')) + '; display: flex; justify-content: space-between; align-items: center;">' +
              '<div>' +
                '<div style="font-weight: 700; font-size: 0.85rem; color: ' + (isRevoked ? '#94a3b8' : '#f8fafc') + ';">' + icon + ' ' + s.deviceName + ' ' + (isCurrent ? '(This Device)' : '') + '</div>' +
                '<div style="font-size: 0.7rem; color: #64748b; font-family: monospace;">IP: ' + s.ipAddress + ' &bull; ' + dateStr + '</div>' +
              '</div>';

            if (isRevoked) {
              html += '<span style="font-size: 0.7rem; background: rgba(239, 68, 68, 0.2); color: #f87171; padding: 3px 8px; border-radius: 6px; font-weight: 700;">Revoked 🚫</span>';
            } else if (isCurrent) {
              html += '<span style="font-size: 0.7rem; background: rgba(16, 185, 129, 0.2); color: #10b981; padding: 3px 8px; border-radius: 6px; font-weight: 700;">Active Now</span>';
            } else {
              html += '<button onclick="triggerRemoteLogoutDevice(&quot;' + s.sessionId + '&quot;, &quot;' + s.deviceName.replace(/"/g, '&quot;') + '&quot;)" style="padding: 5px 10px; background: rgba(239, 68, 68, 0.15); color: #f87171; border: 1px solid rgba(239, 68, 68, 0.4); border-radius: 6px; font-size: 0.75rem; font-weight: 700; cursor: pointer;">Remote Logout 🚨</button>';
            }
            html += '</div>';
          }
          container.innerHTML = html;
        })
        .catch(function(err) {
          container.innerHTML = '<div style="color: #ef4444; font-size: 0.82rem; padding: 1rem; text-align: center;">Error contacting session coordinator: ' + err.message + '</div>';
        });
    }

    function revokeAllOtherSessions() {
      const token = localStorage.getItem('sovra_session_token') || (myProfile && myProfile.sessionToken) || '';
      if (!token) return;
      if (!confirm('Are you sure you want to log out all other devices? Only this browser session will stay active.')) return;

      fetch('/api/user/sessions', { headers: { 'Authorization': 'Bearer ' + token } })
        .then(r => r.json())
        .then(async data => {
          if (data && data.ok && Array.isArray(data.sessions)) {
            const others = data.sessions.filter(s => !s.isCurrent && !s.isRevoked);
            for (const s of others) {
              await fetch('/api/user/sessions/revoke', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
                body: JSON.stringify({ sessionId: s.sessionId })
              });
            }
            showAccountToast('🚨 All ' + others.length + ' remote sessions revoked successfully!', 'success');
            loadRealConnectedDevices();
          }
        })
        .catch(err => showAccountToast('Error revoking sessions: ' + err.message, 'error'));
    }

    function triggerRemoteLogoutDevice(sessionId, deviceName) {
      const token = (typeof myProfile !== 'undefined' && myProfile && myProfile.sessionToken)
        ? myProfile.sessionToken
        : localStorage.getItem('sovra_session_token');

      const headers = { 'Content-Type': 'application/json' };
      if (token) headers['Authorization'] = 'Bearer ' + token;

      fetch('/api/user/sessions/revoke', {
        method: 'POST',
        headers: headers,
        body: JSON.stringify({ sessionId: sessionId })
      })
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (data && data.ok) {
          showAccountToast('🚨 Remote logout verified! Session "' + deviceName + '" was wiped permanently.', 'success');
          loadRealConnectedDevices();
        } else {
          alert('Failed to revoke session: ' + (data?.error || 'Unknown error'));
        }
      })
      .catch(function(err) { alert('Error: ' + err.message); });
    }

    async function triggerBiometricAccountCreation() {
      const nameInput = document.getElementById('womNameInput');
      const handleInput = document.getElementById('womHandleInput');
      const pinInput = document.getElementById('womRegisterPinInput');
      const submitBtn = document.getElementById('womRegisterSubmitBtn');
      const errorBox = document.getElementById('womErrorMsg');

      const nameVal = (nameInput && nameInput.value.trim()) ? nameInput.value.trim() : '';
      const handleVal = (handleInput && handleInput.value.trim()) ? handleInput.value.trim().replace(/^@/, '') : '';
      const pinVal = (pinInput && pinInput.value.trim()) ? pinInput.value.trim() : '123456';

      if (!handleVal) {
        if (errorBox) {
          errorBox.innerText = 'Please choose a sovereign handle.';
          errorBox.style.display = 'block';
        }
        return;
      }

      const fullName = nameVal || (handleVal.charAt(0).toUpperCase() + handleVal.slice(1));
      const cleanHandle = '@' + handleVal.toLowerCase();

      // UI Loading Feedback
      const originalBtnHtml = submitBtn ? submitBtn.innerHTML : '';
      if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.style.opacity = '0.7';
        submitBtn.innerHTML = '<span>Creating Sovereign Identity... ⏳</span>';
      }
      if (errorBox) {
        errorBox.style.display = 'none';
      }

      function restoreSubmitBtn() {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.style.opacity = '1';
          submitBtn.innerHTML = originalBtnHtml;
        }
      }

      // Dynamic Client-Side Proof-of-Work Solver (Botnet & Sybil Defense)
      let powPayload = {};
      try {
        const chRes = await fetch('/api/auth/challenge', {
          headers: { 'bypass-tunnel-reminder': 'true' }
        });
        if (chRes.ok) {
          const chData = await chRes.json();
          if (chData.ok && chData.challengeId && chData.prefix) {
            const target = '0'.repeat(chData.difficulty || 3);
            let nonce = 0;
            const startTime = Date.now();
            while (nonce < 50000 && (Date.now() - startTime < 2000)) {
              if (window.crypto && crypto.subtle) {
                const msgBuf = new TextEncoder().encode(chData.prefix + nonce);
                const hashBuf = await crypto.subtle.digest('SHA-256', msgBuf);
                const hashArr = Array.from(new Uint8Array(hashBuf));
                const hashHex = hashArr.map(b => b.toString(16).padStart(2, '0')).join('');
                if (hashHex.startsWith(target)) {
                  powPayload = { challengeId: chData.challengeId, solutionNonce: String(nonce) };
                  break;
                }
              }
              nonce++;
            }
          }
        }
      } catch (powErr) {}

      try {
        const res = await fetch('/api/user/register', {
          method: 'POST',
          headers: { 
            'Content-Type': 'application/json',
            'bypass-tunnel-reminder': 'true'
          },
          body: JSON.stringify({
            handle: cleanHandle,
            name: fullName,
            device: isMobileDevice ? 'Mobile' : 'Desktop',
            avatar: womSelectedAvatarEmoji || fullName.charAt(0).toUpperCase(),
            avatarDataUrl: womSelectedAvatarDataUrl || undefined,
            securityPin: pinVal,
            ...powPayload,
          })
        });

        let data;
        const text = await res.text();
        try {
          data = JSON.parse(text);
        } catch (jsonErr) {
          restoreSubmitBtn();
          if (errorBox) {
            errorBox.innerText = 'Server returned proxy notice (' + res.status + '): ' + text.slice(0, 120);
            errorBox.style.display = 'block';
          }
          return;
        }

        if (!res.ok || !data.ok) {
          restoreSubmitBtn();
          if (errorBox) {
            errorBox.innerText = data.error || 'Registration failed. Handle may already be taken.';
            errorBox.style.display = 'block';
          }
          return;
        }

        if (errorBox) errorBox.style.display = 'none';
        myProfile = data.user;
        currentUserHandle = myProfile.handle;

        localStorage.removeItem('sovra_logged_out');
        try {
          localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile));
          if (data.sessionToken) localStorage.setItem('sovra_session_token', data.sessionToken);
        } catch (e) {}

        fetch('/api/peers/register', {
          method: 'POST',
          headers: { 
            'Content-Type': 'application/json',
            'bypass-tunnel-reminder': 'true'
          },
          body: JSON.stringify(myProfile)
        }).catch(function() {});

        document.getElementById('womStep1').style.display = 'none';
        document.getElementById('womStep2').style.display = 'block';

        setTimeout(() => {
          document.getElementById('womStep2').style.display = 'none';
          document.getElementById('womStep3').style.display = 'block';
          if (typeof updateOnboardingFollowsCountUI === 'function') updateOnboardingFollowsCountUI();
        }, 1000);
      } catch (err) {
        restoreSubmitBtn();
        if (errorBox) {
          errorBox.innerText = 'Network connection failed: ' + (err.message || err);
          errorBox.style.display = 'block';
        }
      }
    }

