    function showInAppNotification(notif) {
      if (!notif) return;
      var title = (typeof notif === "string") ? "Notification" : (notif.title || "Sovra Notification");
      var body = (typeof notif === "string") ? notif : (notif.body || "");
      var type = (typeof notif === "object" && notif) ? (notif.type || "") : "";
      var senderDid = (typeof notif === "object" && notif) ? (notif.senderDid || (notif.data && (notif.data.senderDid || notif.data.fromDid || notif.data.friendDid)) || "") : "";
      var senderName = (typeof notif === "object" && notif) ? (notif.senderName || (notif.data && notif.data.senderName) || "") : "";
      var senderHandle = (typeof notif === "object" && notif) ? (notif.senderHandle || (notif.data && notif.data.senderHandle) || "") : "";
      var id = (typeof notif === "object" && notif) ? (notif.id || "") : "";

      // Deduplication: prevent identical alerts within 4000ms
      var dedupKey = (title + "|" + body).trim();
      var now = Date.now();
      if (_recentInAppNotifMap.has(dedupKey) && (now - _recentInAppNotifMap.get(dedupKey)) < 4000) {
        return;
      }
      _recentInAppNotifMap.set(dedupKey, now);

      if (_recentInAppNotifMap.size > 50) {
        _recentInAppNotifMap.forEach(function(ts, k) {
          if (now - ts > 12000) _recentInAppNotifMap.delete(k);
        });
      }

      var container = document.getElementById("sovraInAppBannerContainer");
      if (!container) {
        container = document.createElement("div");
        container.id = "sovraInAppBannerContainer";
        container.className = "sovra-inapp-banner-container";
        document.body.appendChild(container);
      }

      // STRICT CONCURRENCY: Maximum 2 cards on screen. If 2 exist, dismiss oldest.
      var existingCards = container.querySelectorAll(".sovra-inapp-banner:not(.dismissing)");
      if (existingCards.length >= 2) {
        var oldest = existingCards[0];
        oldest.classList.add("dismissing");
        setTimeout(function() { if (oldest.parentNode) oldest.parentNode.removeChild(oldest); }, 220);
      } else if (existingCards.length === 1) {
        existingCards[0].classList.add("stacked-behind");
      }

      var banner = document.createElement("div");
      banner.className = "sovra-inapp-banner";
      banner.setAttribute("role", "alert");

      var isCall = type === "call" || body.includes("calling you");
      var isFriendReq = type === "friend_request" || body.includes("sent you a friend request");
      var isFriendAccept = type === "friend_accept" || body.includes("accepted your friend request");
      var isMsg = type === "message" || type === "chat" || body.includes("Encrypted Message");

      var iconEmoji = "🔔";
      var badgeBg = "rgba(99, 102, 241, 0.2)";
      var badgeColor = "#818cf8";
      var badgeEmoji = "🔔";

      if (isCall) {
        iconEmoji = "📞";
        badgeBg = "rgba(34, 197, 94, 0.2)";
        badgeColor = "#22c55e";
        badgeEmoji = "📞";
      } else if (isFriendReq) {
        iconEmoji = "👥";
        badgeBg = "rgba(99, 102, 241, 0.2)";
        badgeColor = "#818cf8";
        badgeEmoji = "👥";
      } else if (isFriendAccept) {
        iconEmoji = "🤝";
        badgeBg = "rgba(245, 158, 11, 0.2)";
        badgeColor = "#fbbf24";
        badgeEmoji = "🤝";
      } else if (isMsg) {
        iconEmoji = "💬";
        badgeBg = "rgba(56, 189, 248, 0.2)";
        badgeColor = "#38bdf8";
        badgeEmoji = "🔒";
      }

      var avatarHtml = '<div class="sovra-banner-avatar-wrap" style="background: ' + badgeBg + '; color: ' + badgeColor + ';">' +
        '<span>' + iconEmoji + '</span>' +
        '<span class="sovra-banner-badge" style="background: ' + badgeBg + '; color: ' + badgeColor + ';">' + badgeEmoji + '</span>' +
      '</div>';

      var actionBtnHtml = "";
      if (isCall) {
        actionBtnHtml = '<button type="button" class="sovra-banner-btn-action" style="background: #22c55e; color: #0b141a;">Answer</button>';
      } else if (isFriendReq) {
        actionBtnHtml = '<button type="button" class="sovra-banner-btn-action" style="background: #22c55e; color: #0b141a;">Accept</button>';
      } else if (isMsg) {
        actionBtnHtml = '<button type="button" class="sovra-banner-btn-action" style="background: rgba(56, 189, 248, 0.18); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.35);">Reply</button>';
      }

      banner.innerHTML = avatarHtml +
        '<div class="sovra-banner-content">' +
          '<div class="sovra-banner-title-row">' +
            '<span class="sovra-banner-title">' + (_sanitizeToastHtml(title) || "Notification") + '</span>' +
            '<span class="sovra-banner-time">just now</span>' +
          '</div>' +
          '<div class="sovra-banner-body">' + (_sanitizeToastHtml(body) || "") + '</div>' +
        '</div>' +
        '<div class="sovra-banner-actions">' +
          actionBtnHtml +
          '<button type="button" class="sovra-banner-btn-close" title="Dismiss">✕</button>' +
        '</div>';

      function dismissBanner() {
        banner.classList.add("dismissing");
        setTimeout(function() {
          if (banner.parentNode) banner.parentNode.removeChild(banner);
          var rem = container.querySelectorAll(".sovra-inapp-banner.stacked-behind");
          if (rem.length > 0) {
            rem[rem.length - 1].classList.remove("stacked-behind");
          }
        }, 220);
      }

      banner.onclick = function(e) {
        if (e && e.target && e.target.classList.contains("sovra-banner-btn-close")) {
          e.stopPropagation();
          dismissBanner();
          return;
        }
        if (e && e.target && e.target.classList.contains("sovra-banner-btn-action")) {
          e.stopPropagation();
          dismissBanner();
          if (isCall && typeof acceptSpatialCall === "function") {
            acceptSpatialCall();
          } else if (isFriendReq && typeof switchTab === "function") {
            switchTab("friends");
          } else if (isMsg && typeof openDirectChatWithUser === "function" && senderDid) {
            openDirectChatWithUser(senderDid, senderName, senderHandle);
          } else if (typeof handleNotificationClick === "function") {
            handleNotificationClick(id, type, senderDid, e, senderName, senderHandle);
          }
          return;
        }
        dismissBanner();
        if (typeof handleNotificationClick === "function") {
          handleNotificationClick(id, type, senderDid, e, senderName, senderHandle);
        }
      };

      // Swipe up to dismiss gesture on mobile
      var startY = 0;
      banner.addEventListener("touchstart", function(e) {
        if (e.touches && e.touches[0]) startY = e.touches[0].clientY;
      }, { passive: true });
      banner.addEventListener("touchmove", function(e) {
        if (!e.touches || !e.touches[0]) return;
        var diff = e.touches[0].clientY - startY;
        if (diff < -10) {
          banner.style.transform = "translateY(" + diff + "px)";
          banner.style.opacity = String(Math.max(0, 1 + diff / 60));
        }
      }, { passive: true });
      banner.addEventListener("touchend", function(e) {
        if (!e.changedTouches || !e.changedTouches[0]) return;
        var diff = e.changedTouches[0].clientY - startY;
        if (diff < -25) {
          dismissBanner();
        } else {
          banner.style.transform = "";
          banner.style.opacity = "";
        }
      }, { passive: true });

      container.appendChild(banner);

      if (typeof navigator !== "undefined" && navigator.vibrate) {
        try { navigator.vibrate(35); } catch (_) {}
      }

      var dismissTimeout = setTimeout(dismissBanner, 4500);
      banner.onmouseenter = function() { clearTimeout(dismissTimeout); };
      banner.onmouseleave = function() { dismissTimeout = setTimeout(dismissBanner, 2200); };
    }
