    function showAccountToast(msg, type) {
      if (!msg) return;
      var str = String(msg);

      // Route in-app social/call alerts to top heads-up banner
      if (str.includes("sent you a friend request") || str.includes("accepted your friend request") ||
          str.includes("is calling you") || str.includes("End-to-End Encrypted Message") ||
          str.includes("liked your post") || str.includes("commented on your post") ||
          str.includes("replied to your comment") || (type === "notification")) {
        showInAppNotification({
          title: str.includes("calling you") ? "Incoming Call" :
                 (str.includes("sent you a friend request") ? "Friend Request" :
                 (str.includes("accepted your friend request") ? "Friend Request Accepted" :
                 (str.includes("Encrypted Message") ? "New Encrypted Message" : "Notification"))),
          body: str.replace(/^[👥🤝💬🔔⚡❤️🗨️\s]+/, ""),
          type: str.includes("calling you") ? "call" :
                (str.includes("sent you a friend request") ? "friend_request" :
                (str.includes("accepted your friend request") ? "friend_accept" :
                (str.includes("Encrypted Message") ? "message" : "notification")))
        });
        return;
      }

      const t = document.getElementById("accountNoticeToast");
      if (t) {
        t.innerText = str;
        t.style.display = "block";
        setTimeout(() => { if (t) t.style.display = "none"; }, 4000);
      }

      let container = document.getElementById("globalToastContainer");
      if (!container) {
        container = document.createElement("div");
        container.id = "globalToastContainer";
        container.className = "sovra-floating-toast-container";
        document.body.appendChild(container);
      }

      // STRICT CONCURRENCY: Strictly MAX 1 visible bottom toast. Dismiss previous immediately.
      while (container.firstChild) {
        container.removeChild(container.firstChild);
      }

      const toast = document.createElement("div");
      toast.className = "sovra-floating-toast";
      let borderColor = "rgba(56, 189, 248, 0.45)";
      let glowColor = "rgba(56, 189, 248, 0.22)";
      if (type === "error" || str.includes("⚠️") || str.includes("🚫") || str.includes("Failed") || str.includes("Incorrect")) {
        borderColor = "rgba(239, 68, 68, 0.6)";
        glowColor = "rgba(239, 68, 68, 0.3)";
      } else if (type === "success" || str.includes("✓") || str.includes("🎉") || str.includes("Copied") || str.includes("verified") || str.includes("Unlocked")) {
        borderColor = "rgba(52, 211, 153, 0.6)";
        glowColor = "rgba(52, 211, 153, 0.3)";
      }
      toast.style.borderColor = borderColor;
      toast.style.boxShadow = "0 12px 32px rgba(0, 0, 0, 0.65), 0 0 16px " + glowColor;
      toast.innerHTML = "<span>" + str + "</span>";

      container.appendChild(toast);
      if (typeof navigator !== "undefined" && navigator.vibrate) {
        try { navigator.vibrate(35); } catch (_) {}
      }

      setTimeout(function() {
        if (!toast.parentNode) return;
        toast.style.opacity = "0";
        toast.style.transform = "translateY(12px) scale(0.95)";
        setTimeout(function() {
          if (toast.parentNode) toast.parentNode.removeChild(toast);
        }, 260);
      }, 3000);
    }
