    function submitCreateCommunity() {
      const nameInput = document.getElementById('newCommNameInput');
      const descInput = document.getElementById('newCommDescInput');
      const tagsInput = document.getElementById('newCommTagsInput');
      const privacySelect = document.getElementById('newCommPrivacySelect');
      const colorSelect = document.getElementById('newCommColorSelect');

      const name = nameInput ? nameInput.value.trim() : '';
      if (!name || name.length < 2) {
        if (typeof showAccountToast === 'function') showAccountToast('Please provide a community name (at least 2 characters).');
        return;
      }

      const desc = descInput ? descInput.value.trim() : '';
      const rawTags = tagsInput ? tagsInput.value.trim() : '';
      const tags = rawTags ? rawTags.split(/[\s,]+/).filter(Boolean).map(t => t.replace(/^#/, '')) : ['community'];
      const privacy = privacySelect ? privacySelect.value : 'public';
      const color = colorSelect ? colorSelect.value : '#3b82f6';
      const emoji = _selectedCommEmoji || '🌐';

      const newId = 'comm-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7);
      const myDid = (typeof myProfile !== 'undefined' && myProfile && myProfile.did) ? myProfile.did : '';

      const newComm = {
        id: newId,
        name: name,
        description: desc || 'Sovereign peer community dedicated to ' + name,
        emoji: emoji,
        avatarBg: color,
        category: 'General',
        tags: tags,
        membersCount: 1,
        postsToday: 1,
        privacy: privacy,
        isJoined: true,
        isCreator: true
      };

      if (!communitiesStore) communitiesStore = [];
      communitiesStore.unshift(newComm);
      persistCommunitiesStore();
      closeCreateCommunityModal();

      if (typeof showAccountToast === 'function') {
        showAccountToast('🌐 Community "' + name + '" created successfully on peer mesh!');
      }

      const token = (typeof window.getEffectiveSessionToken === 'function') ? window.getEffectiveSessionToken() : (localStorage.getItem('sovra_session_token') || '');
      const authHeaders = (typeof getAuthHeaders === 'function') ? getAuthHeaders() : { 'Content-Type': 'application/json' };
      fetch('/api/social/groups', {
        method: 'POST',
        headers: authHeaders,
        body: JSON.stringify({
          name: name,
          description: desc,
          tags: tags,
          privacy: privacy,
          emoji: emoji,
          avatarBg: color,
          userDid: myDid,
          sessionToken: token
        })
      }).then(r => r.json()).then(res => {
        if (res && res.ok && res.group && res.group.id) {
          newComm.id = res.group.id;
          persistCommunitiesStore();
        }
      }).catch(() => {});

      switchCommunitiesSubtab('created');
    }

    function enterCommunitySpace(id, name) {
      if (typeof showAccountToast === 'function') {
        showAccountToast('Entering community: ' + name);
      }
      switchTab('feed');
    }

    // --- Module 9: SOVRA Unified Search Engine ---
    let _activeSearchCategory = 'all';

    function handleUnifiedSearch(query) {
      const q = (query || '').trim();
      const clearBtn = document.getElementById('clearUnifiedSearchBtn');
      if (clearBtn) clearBtn.style.display = q ? 'block' : 'none';

      const resultsContainer = document.getElementById('searchResultsContainer');
      const mosaicSection = document.getElementById('exploreMosaicSection');
      const recentSection = document.getElementById('recentSearchesSection');

      if (q) {
        if (resultsContainer) resultsContainer.style.display = 'block';
        if (mosaicSection) mosaicSection.style.display = 'none';
        if (recentSection) recentSection.style.display = 'none';
        renderSearchResults(q, _activeSearchCategory);
      } else {
        if (resultsContainer) resultsContainer.style.display = 'none';
        if (mosaicSection) mosaicSection.style.display = 'block';
        if (recentSection) recentSection.style.display = 'block';
      }
    }

    function clearUnifiedSearch() {
      const inp = document.getElementById('unifiedSearchPageInput');
      if (inp) { inp.value = ''; inp.focus(); }
      handleUnifiedSearch('');
    }

    function applySearchQuery(query) {
      const inp = document.getElementById('unifiedSearchPageInput');
      if (inp) inp.value = query;
      handleUnifiedSearch(query);
    }

    function clearRecentSearches() {
      const sec = document.getElementById('recentSearchesSection');
      if (sec) sec.style.display = 'none';
      try { localStorage.removeItem('sovra_recent_searches'); } catch (_) {}
    }

    function removeSearchChip(btn, e) {
      if (e) e.stopPropagation();
      const chip = btn.closest('.search-chip');
      if (chip && chip.parentNode) chip.parentNode.removeChild(chip);
    }

    function filterSearchCategory(cat, pillBtn) {
      _activeSearchCategory = cat;
      const pills = document.querySelectorAll('#exploreCategoryTabs .search-cat-pill');
      pills.forEach(p => p.classList.remove('active'));
      if (pillBtn) pillBtn.classList.add('active');

      const resultsContainer = document.getElementById('searchResultsContainer');
      const mosaicSection = document.getElementById('exploreMosaicSection');
      const recentSection = document.getElementById('recentSearchesSection');

      if (cat === 'people' || cat === 'communities') {
        if (mosaicSection) mosaicSection.style.display = 'none';
        if (resultsContainer) resultsContainer.style.display = 'block';
        if (recentSection) recentSection.style.display = 'none';
        const inp = document.getElementById('unifiedSearchPageInput');
        renderSearchResults(inp ? inp.value.trim() : '', cat);
      } else {
        const inp = document.getElementById('unifiedSearchPageInput');
        if (inp && inp.value.trim()) {
          renderSearchResults(inp.value.trim(), cat);
        } else {
          filterExploreCategory(cat, pillBtn);
        }
      }
    }

    function renderSearchResults(query, category) {
      const container = document.getElementById('searchResultsContainer');
      if (!container) return;

      const q = (query || '').toLowerCase().trim();
      const cat = category || 'all';

      if (!q && cat === 'all') {
        container.innerHTML = '<div style="padding: 28px; text-align: center; color: #64748b; font-size: 0.88rem; background: rgba(255,255,255,0.02); border-radius: 14px; border: 1px dashed rgba(255,255,255,0.08);">' +
          '<div style="font-size: 1.8rem; margin-bottom: 8px;">🔍</div>' +
          '<div>Type a search query or select a topic to search across people, videos, reels, posts, and communities.</div>' +
          '</div>';
        return;
      }

      const items = [];

      // 1. People / Contacts
      const peersPool = (typeof contactsStore !== 'undefined' && Array.isArray(contactsStore) && contactsStore.length > 0)
        ? contactsStore
        : [
            { id: 'rohit', name: 'Rohit Kumar', handle: '@rohit_live', did: 'did:sovra:rohit', role: 'Core Protocol Dev' },
            { id: 'aarav', name: 'Aarav Sharma', handle: '@aarav', did: 'did:sovra:aarav', role: 'Distributed Systems Engineer' },
            { id: 'elena', name: 'Elena Rostova', handle: '@elena_dev', did: 'did:sovra:elena', role: 'Cryptographic Security Lead' },
            { id: 'maya', name: 'Maya Lin', handle: '@maya_creative', did: 'did:sovra:maya', role: 'Lead Visual Designer' }
          ];

      peersPool.forEach(p => {
        items.push({
          type: 'people',
          id: p.id || p.did || p.handle,
          title: p.name || p.displayName || 'Peer User',
          subtitle: (p.handle ? p.handle : '@peer') + (p.role ? ' • ' + p.role : (p.statusText ? ' • ' + p.statusText : ' • Verified Sovereign Peer')),
          icon: '👤',
          action: "if(typeof openPeerProfileById==='function'){ openPeerProfileById('" + (p.id || p.did || '') + "'); } else { switchTab('me'); }"
        });
      });

      // 2. Videos Catalog
      const videosPool = (typeof ytVideosCatalog !== 'undefined' && Array.isArray(ytVideosCatalog) && ytVideosCatalog.length > 0)
        ? ytVideosCatalog
        : [
            { id: 'yt-1', title: 'Decentralized P2P Mesh Architecture (4K)', creator: 'SOVRA Core', views: '18.4K views', duration: '42:15' },
            { id: 'yt-2', title: 'Cellular CGNAT Traversal Deep Dive', creator: 'Mesh Protocols', views: '9.2K views', duration: '28:40' },
            { id: 'yt-3', title: 'WebGPU Shader Performance on Mobile', creator: 'GPU Devs', views: '14.1K views', duration: '19:12' },
            { id: 'yt-4', title: 'Zero-Knowledge Proofs in Rust', creator: 'ZK Cryptography', views: '31.5K views', duration: '55:00' }
          ];

      videosPool.forEach((v, idx) => {
        items.push({
          type: 'videos',
          id: v.id || ('vid-' + idx),
          title: v.title || 'SOVRA Video',
          subtitle: (v.creator || 'SOVRA Video') + ' • ' + (v.views || '12K views') + ' • ' + (v.duration || '15:00'),
          icon: '📺',
          action: "switchTab('youtube'); if(typeof renderYtVideo==='function'){ renderYtVideo(" + idx + ", true); }"
        });
      });

      // 3. Communities
      if (!communitiesStore || communitiesStore.length === 0) initCommunitiesStore();
      (communitiesStore || []).forEach(c => {
        items.push({
          type: 'communities',
          id: c.id,
          title: c.name,
          subtitle: (c.emoji || '🌐') + ' SOVRA Community • ' + (c.membersCount ? (c.membersCount >= 1000 ? (c.membersCount / 1000).toFixed(1) + 'K' : c.membersCount) : '10') + ' Members • ' + (c.postsToday || 25) + ' posts today',
          icon: c.emoji || '🌐',
          action: "switchTab('communities'); switchCommunitiesSubtab('explore');"
        });
      });

      // 4. Feed Posts
      const feedPosts = (typeof feedPostsData !== 'undefined' && Array.isArray(feedPostsData)) ? feedPostsData : [];
      feedPosts.forEach(fp => {
        items.push({
          type: 'posts',
          id: fp.id,
          title: fp.caption ? (fp.caption.length > 70 ? fp.caption.slice(0, 67) + '...' : fp.caption) : 'SOVRA Feed Post',
          subtitle: 'Post by ' + (fp.authorName || '@peer') + ' • ' + (fp.likesCount || 0) + ' likes',
          icon: '📝',
          action: "switchTab('feed'); setTimeout(function(){ var el = document.getElementById('card-" + fp.id + "'); if(el) el.scrollIntoView({behavior:'smooth', block:'center'}); }, 100);"
        });
      });

      // 5. PIDDI Reels
      const reelsPool = (typeof reelsData !== 'undefined' && Array.isArray(reelsData)) ? reelsData : [];
      reelsPool.forEach((r, idx) => {
        items.push({
          type: 'reels',
          id: r.id,
          title: r.caption ? (r.caption.length > 70 ? r.caption.slice(0, 67) + '...' : r.caption) : 'PIDDI Short Reel',
          subtitle: 'Reel by ' + (r.author || '@creator') + ' • ' + (r.likes || '4.2K') + ' likes',
          icon: '🎬',
          action: "switchTab('reels'); currentReelIndex = " + idx + "; if(typeof renderCurrentReel==='function') renderCurrentReel();"
        });
      });

      const filtered = items.filter(it => {
        const matchesCategory = (cat === 'all' || it.type === cat);
        const matchesQuery = !q || it.title.toLowerCase().includes(q) || it.subtitle.toLowerCase().includes(q);
        return matchesCategory && matchesQuery;
      });

      if (filtered.length === 0) {
        container.innerHTML = '<div style="padding: 36px 16px; text-align: center; color: #94a3b8; font-size: 0.9rem; background: rgba(15,23,42,0.4); border-radius: 14px; border: 1px dashed rgba(255,255,255,0.08);">' +
          '<div style="font-size: 2rem; margin-bottom: 8px;">🔍</div>' +
          'No matching results found for "<strong>' + escapeHtmlClient(query) + '</strong>" in category <em>' + escapeHtmlClient(cat) + '</em>.' +
          '<div style="font-size: 0.78rem; color: #64748b; margin-top: 6px;">Try searching for a creator name, topic tag, or switch category filter to "All".</div>' +
          '</div>';
        return;
      }

      container.innerHTML = '<div style="font-size: 0.76rem; font-weight: 700; color: #64748b; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 10px;">Results (' + filtered.length + ')</div>' +
        filtered.map(it => {
          const typeBadgeColor = it.type === 'people' ? '#38bdf8' : (it.type === 'videos' ? '#ef4444' : (it.type === 'communities' ? '#8b5cf6' : (it.type === 'reels' ? '#ec4899' : '#10b981')));
          return '<div class="search-result-row" onclick="' + it.action + '" style="display: flex; align-items: center; justify-content: space-between; padding: 12px 16px; background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255,255,255,0.06); border-radius: 14px; cursor: pointer; transition: all 0.18s ease; margin-bottom: 8px;">' +
            '<div style="display: flex; align-items: center; gap: 12px; min-width: 0; flex: 1;">' +
              '<div style="width: 40px; height: 40px; border-radius: 10px; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); display: flex; align-items: center; justify-content: center; font-size: 1.25rem; flex-shrink: 0;">' + it.icon + '</div>' +
              '<div style="min-width: 0; flex: 1;">' +
                '<div style="font-weight: 700; font-size: 0.9rem; color: #f8fafc; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">' + escapeHtmlClient(it.title) + '</div>' +
                '<div style="font-size: 0.74rem; color: #94a3b8; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; margin-top: 2px;">' + escapeHtmlClient(it.subtitle) + '</div>' +
              '</div>' +
            '</div>' +
            '<div style="display: flex; align-items: center; gap: 8px; flex-shrink: 0; margin-left: 12px;">' +
              '<span style="font-size: 0.68rem; text-transform: uppercase; font-weight: 700; padding: 2px 7px; border-radius: 6px; background: rgba(255,255,255,0.05); color: ' + typeBadgeColor + ';">' + escapeHtmlClient(it.type) + '</span>' +
              '<span style="font-size: 0.78rem; color: #38bdf8; font-weight: 700;">Open →</span>' +
            '</div>' +
          '</div>';
        }).join('');
    }

    // --- Instagram Visual Discovery Parity: Explore Mosaic Grid Engine ---
    function filterExploreCategory(category, pillBtn) {
      const pills = document.querySelectorAll('#exploreCategoryTabs .search-cat-pill');
      pills.forEach(p => p.classList.remove('active'));
      if (pillBtn) pillBtn.classList.add('active');

      const gridSection = document.getElementById('exploreMosaicSection');
      const resultsSection = document.getElementById('searchResultsContainer');
      const recentSection = document.getElementById('recentSearchesSection');

      if (category === 'people' || category === 'communities') {
        if (gridSection) gridSection.style.display = 'none';
        if (resultsSection) resultsSection.style.display = 'block';
        if (recentSection) recentSection.style.display = 'none';
        filterSearchCategory(category, pillBtn);
        return;
      }

      if (gridSection) gridSection.style.display = 'block';
      if (resultsSection) resultsSection.style.display = 'none';
      loadExploreMosaicGrid(category);
    }

    function loadExploreMosaicGrid(category) {
      const grid = document.getElementById('exploreMosaicGrid');
      if (!grid) return;

      const catParam = category || 'all';
      grid.innerHTML = '<div style="grid-column: 1 / -1; text-align: center; padding: 30px; color: #64748b;">Loading visual discovery grid...</div>';

      fetch('/api/explore/grid?category=' + encodeURIComponent(catParam) + '&limit=24')
      .then(r => r.json())
      .then(data => {
        if (data.ok && Array.isArray(data.items)) {
          if (data.items.length === 0) {
            grid.innerHTML = '<div style="grid-column: 1 / -1; text-align: center; padding: 40px; color: #94a3b8;">No visual media found in this category yet. Create the first reel or photo post!</div>';
            return;
          }

          grid.innerHTML = data.items.map(item => {
            const spanClass = item.layoutSpan === '1x2' ? 'span-1x2' : (item.layoutSpan === '2x2' ? 'span-2x2' : 'span-1x1');
            const isReel = item.type === 'reel';
            const fPreset = item.filterPreset ? 'filter-' + item.filterPreset : '';
            const fCss = item.cssFilter ? 'filter: ' + item.cssFilter + ';' : '';

            let mediaHtml = '';
            if (isReel && item.videoUrl) {
              mediaHtml = '<video src="' + item.videoUrl + '" playsinline muted loop style="width: 100%; height: 100%; object-fit: cover;" onmouseover="this.play().catch(function(){})" onmouseout="this.pause()"></video>';
            } else if (item.thumbnailUrl) {
              mediaHtml = '<img src="' + item.thumbnailUrl + '" class="' + fPreset + '" style="' + fCss + ' width: 100%; height: 100%; object-fit: cover;" loading="lazy" />';
            } else {
              mediaHtml = '<div style="width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; background: linear-gradient(135deg, #1e1b4b, #312e81); color: #fff; font-size: 1.8rem;">✨</div>';
            }

            return '<div class="explore-tile ' + spanClass + '" onclick="handleExploreTileClick(&quot;' + item.type + '&quot;, &quot;' + item.id + '&quot;)">' +
              mediaHtml +
              '<div class="explore-tile-overlay">' +
                '<div style="font-weight: 700; font-size: 0.85rem; color: #fff; margin-bottom: 2px;">' + (item.authorName || item.creatorHandle || 'Sovereign') + '</div>' +
                '<div style="font-size: 0.72rem; color: #cbd5e1; display: flex; gap: 8px;">' +
                  '<span>❤️ ' + (item.likesCount || 0) + '</span>' +
                  '<span>💬 ' + (item.commentsCount || 0) + '</span>' +
                '</div>' +
              '</div>' +
              (isReel ? '<div class="explore-tile-badge reel">🎬 Reel</div>' : (item.isCarousel ? '<div class="explore-tile-badge carousel">📷 Carousel</div>' : '')) +
            '</div>';
          }).join('');
        }
      })
      .catch(err => {
        grid.innerHTML = '<div style="grid-column: 1 / -1; text-align: center; padding: 30px; color: #ef4444;">Failed to load visual discovery items</div>';
      });
    }

    function handleExploreTileClick(type, id) {
      if (type === 'reel') {
        switchTab('reels');
        const rIdx = reelsData.findIndex(r => r.id === id);
        if (rIdx >= 0) {
          currentReelIndex = rIdx;
          renderCurrentReel();
        }
      } else {
        switchTab('feed');
        setTimeout(() => {
          const card = document.getElementById('card-' + id);
          if (card) card.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }, 120);
      }
    }

