    function renderShareModalContacts(query) {
      const listEl = document.getElementById('shareModalContactsList');
      if (!listEl) return;

      let list = (typeof contactsData !== 'undefined' && Array.isArray(contactsData) && contactsData.length > 0)
        ? contactsData
        : [
            { did: 'did:sovra:user_c93149ba18ffae32', name: 'Priya Patel', handle: '@priya', isOnline: true, avatar: 'P', avatarBg: '#ec4899' },
            { did: 'did:sovra:user_81f20ae19b4e5421', name: 'Rahul Sharma', handle: '@rahul', isOnline: true, avatar: 'R', avatarBg: '#6366f1' },
            { did: 'did:sovra:user_48a129ef31045239', name: 'Alice Chen', handle: '@alice', isOnline: false, avatar: 'A', avatarBg: '#10b981' },
            { did: 'did:sovra:user_77ba418293ed1094', name: 'Bob Sovereign', handle: '@bob', isOnline: true, avatar: 'B', avatarBg: '#f59e0b' }
          ];

      const q = (query || '').toLowerCase().trim();
      if (q) {
        list = list.filter(function(c) {
          return (c.name && c.name.toLowerCase().includes(q)) ||
                 (c.handle && c.handle.toLowerCase().includes(q)) ||
                 (c.did && c.did.toLowerCase().includes(q));
        });
      }

      if (list.length === 0) {
        listEl.innerHTML = '<div style="text-align: center; color: #64748b; font-size: 0.78rem; padding: 1.5rem 0;">No matching contacts found</div>';
        return;
      }

      let html = '';
      list.forEach(function(c) {
        const cName = safeHtmlStr(c.name || 'Peer');
        const cHandle = safeHtmlStr(c.handle || '@peer');
        const isOnline = Boolean(c.isOnline);
        const av = c.avatar || (cName[0] || 'P');
        const avBg = c.avatarBg || '#6366f1';

        html += '<div style="display: flex; align-items: center; justify-content: space-between; padding: 6px 8px; background: rgba(255, 255, 255, 0.03); border: 1px solid rgba(255, 255, 255, 0.06); border-radius: 10px;">' +
          '<div style="display: flex; align-items: center; gap: 10px; min-width: 0;">' +
            '<div style="position: relative; width: 34px; height: 34px; border-radius: 50%; background: ' + avBg + '; display: flex; align-items: center; justify-content: center; font-size: 0.85rem; font-weight: 700; color: #fff; flex-shrink: 0;">' +
              av +
              (isOnline ? '<span style="position: absolute; bottom: 0; right: 0; width: 9px; height: 9px; border-radius: 50%; background: #10b981; border: 2px solid #0f172a;"></span>' : '') +
            '</div>' +
            '<div style="min-width: 0;">' +
              '<div style="font-size: 0.82rem; font-weight: 700; color: #fff; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">' + cName + '</div>' +
              '<div style="font-size: 0.7rem; color: #94a3b8; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">' + cHandle + '</div>' +
            '</div>' +
          '</div>' +
          '<button type="button" class="share-send-btn" onclick="sendPostToPeerChat(&quot;' + c.did + '&quot;, this)" style="background: rgba(56, 189, 248, 0.15); border: 1px solid rgba(56, 189, 248, 0.35); color: #38bdf8; font-size: 0.74rem; font-weight: 700; padding: 4px 12px; border-radius: 16px; cursor: pointer; transition: all 0.2s ease;">Send</button>' +
        '</div>';
      });

      listEl.innerHTML = html;
    }

    async function sendPostToPeerChat(recipientDid, btnEl) {
      if (!activeSharePost) return;
      const noteInput = document.getElementById('shareModalMessageNote');
      const noteText = noteInput ? noteInput.value.trim() : '';

      if (btnEl) {
        btnEl.disabled = true;
        btnEl.innerText = 'Sending...';
      }

      const token = (typeof myProfile !== 'undefined' && myProfile && myProfile.sessionToken) ? myProfile.sessionToken : (localStorage.getItem('sovra_session_token') || '');
      const headers = { 'Content-Type': 'application/json' };
      if (token) headers['Authorization'] = 'Bearer ' + token;

      const payload = {
        recipientDid: recipientDid,
        text: noteText || ('Shared post from ' + (activeSharePost.authorName || 'Peer')),
        sharedPost: {
          id: activeSharePost.id,
          authorName: activeSharePost.authorName || (activeSharePost.author && activeSharePost.author.name) || 'Peer',
          authorAvatar: activeSharePost.authorAvatar || 'S',
          authorAvatarBg: activeSharePost.authorAvatarBg || '#6366f1',
          authorAvatarDataUrl: activeSharePost.authorAvatarDataUrl,
          caption: activeSharePost.caption || '',
          postType: activeSharePost.postType || 'text',
          mediaImage: activeSharePost.mediaImage,
          mediaVideo: activeSharePost.mediaVideo,
          timestamp: activeSharePost.timestamp || Date.now()
        }
      };

      try {
        const res = await fetch('/api/chat/send', {
          method: 'POST',
          headers: headers,
          body: JSON.stringify(payload)
        });
        const data = await res.json();
        if (data && data.ok) {
          if (btnEl) {
            btnEl.innerText = 'Sent ✓';
            btnEl.style.background = 'rgba(16, 185, 129, 0.2)';
            btnEl.style.borderColor = 'rgba(16, 185, 129, 0.4)';
            btnEl.style.color = '#34d399';
          }
          if (noteInput) noteInput.value = '';
          showAccountToast('✈️ Post sent via direct message!');
          if (typeof syncChatMessages === 'function') syncChatMessages();
        } else {
          if (btnEl) {
            btnEl.disabled = false;
            btnEl.innerText = 'Send';
          }
          showAccountToast('⚠️ Could not send: ' + (data && data.error ? data.error : 'Server rejected'));
        }
      } catch (err) {
        if (btnEl) {
          btnEl.disabled = false;
          btnEl.innerText = 'Send';
        }
        showAccountToast('⚠️ Network error: ' + err.message);
      }
    }

