    let ytPlaybackSpeed = 1.0;
    let ytTheaterMode = false;
    let ytAutoplay = true;
    let ytProgressTimer = null;
    const ytSubscribedMap = {};
    const ytLikedMap = {};
    const ytDislikedMap = {};
    let bellNotificationIndex = 0;
    const bellNotificationOptions = ['all', 'personalized', 'none'];
