    function openClipModal() {
      const v = ytVideosCatalog[activeYtVideoIndex];
      if (!v) return;
      const modal = document.getElementById('ytClipModal');
      if (modal) modal.style.display = 'flex';

      const maxSec = Math.max(30, Math.floor(v.durationSeconds || 300));
      const curSec = Math.floor(ytCurrentTimeSec || 0);

      const startSlider = document.getElementById('ytClipStartSlider');
      const endSlider = document.getElementById('ytClipEndSlider');
      const titleInput = document.getElementById('ytClipTitleInput');

      if (titleInput) titleInput.value = '';

      if (startSlider && endSlider) {
        startSlider.max = String(maxSec);
        endSlider.max = String(maxSec);

        const clipStart = Math.min(curSec, maxSec - 15);
        const clipEnd = Math.min(clipStart + 30, maxSec);

        startSlider.value = String(clipStart);
        endSlider.value = String(clipEnd);
      }
      updateClipRangeTimes();
    }

    function updateClipRangeTimes() {
      const v = ytVideosCatalog[activeYtVideoIndex];
      if (!v) return;
      const startSlider = document.getElementById('ytClipStartSlider');
      const endSlider = document.getElementById('ytClipEndSlider');
      if (!startSlider || !endSlider) return;

      let start = parseInt(startSlider.value, 10);
      let end = parseInt(endSlider.value, 10);

      if (end <= start) {
        end = Math.min(parseInt(startSlider.max, 10), start + 5);
        endSlider.value = String(end);
      }
      if (end - start > 60) {
        end = start + 60;
        endSlider.value = String(end);
      }

      const dur = end - start;
      const rangeLabel = document.getElementById('ytClipRangeLabel');
      const durLabel = document.getElementById('ytClipDurationLabel');

      if (rangeLabel) rangeLabel.innerText = formatYtTime(start) + ' - ' + formatYtTime(end);
      if (durLabel) durLabel.innerText = dur + 's';
    }

    function previewCurrentClip() {
      const startSlider = document.getElementById('ytClipStartSlider');
      if (!startSlider) return;
      const start = parseInt(startSlider.value, 10);
      seekYtTo(start);
      if (!ytIsPlaying) toggleYtPlay();
      if (typeof showAccountToast === 'function') {
        showAccountToast('▶ Previewing clip segment from ' + formatYtTime(start));
      }
    }

    function shareCreatedClip() {
      const v = ytVideosCatalog[activeYtVideoIndex];
      if (!v) return;
      const titleInput = document.getElementById('ytClipTitleInput');
      const title = titleInput ? titleInput.value.trim() : '';
      if (!title) {
        if (typeof showAccountToast === 'function') {
          showAccountToast('⚠️ Please enter a title for your clip');
        }
        if (titleInput) titleInput.focus();
        return;
      }
      const startSlider = document.getElementById('ytClipStartSlider');
      const endSlider = document.getElementById('ytClipEndSlider');
      const start = startSlider ? parseInt(startSlider.value, 10) : 0;
      const end = endSlider ? parseInt(endSlider.value, 10) : 30;

      const origin = window.location.origin || 'https://sovra.network';
      const clipUrl = origin + '/?tab=youtube&v=' + encodeURIComponent(v.id) + '&clip=' + encodeURIComponent(title) + '&start=' + start + '&end=' + end;

      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(clipUrl);
      }
      closeYtModal('ytClipModal');
      spawnConfetti();
      if (typeof showAccountToast === 'function') {
        showAccountToast('✂️ Clip "' + title + '" created & link copied to clipboard!');
      }
    }

    async function refreshYtVideosCatalog() {
      try {
        const resp = await fetch('/api/youtube/videos');
        const data = await resp.json();
        if (data.ok && Array.isArray(data.videos) && data.videos.length > 0) {
          data.videos.forEach(nv => {
            const existingIdx = ytVideosCatalog.findIndex(v => v.id === nv.id);
            if (existingIdx >= 0) {
              ytVideosCatalog[existingIdx] = { ...ytVideosCatalog[existingIdx], ...nv };
            } else {
              ytVideosCatalog.push(nv);
            }
          });
          renderYtRecommendations();
        }
      } catch (err) {
        console.warn('Failed to refresh YouTube video catalog:', err);
      }
    }

    function launchYtPip() {
      if (typeof window.launchYtPip === 'function') {
        window.launchYtPip();
      }
    }

    function pinVideoToLocalBlockstore() {
      const v = ytVideosCatalog[activeYtVideoIndex];
      if (!v) return;
      const btn = document.getElementById('btnDownloadYt');
      if (btn) {
        btn.innerHTML = '<span>⏳</span> <span>Pinning UnixFS DAG...</span>';
        setTimeout(() => {
          btn.innerHTML = '<span>✓</span> <span>Pinned to BitSwap</span>';
          btn.style.borderColor = '#10b981';
          btn.style.color = '#34d399';
          alert('Local Storage Node: 4K Master Video (CID: ipfs://' + v.cid + ') pinned to local 50GB storage pool. Video is now available for offline zero-data streaming and P2P re-seeding!');
        }, 800);
      }
    }

    async function toggleYtSubscribe() {
      const v = ytVideosCatalog[activeYtVideoIndex];
      if (!v) return;
      const btn = document.getElementById('btnSubscribe');
      const counter = document.getElementById('subscribersCountDisplay');
      const bellBtn = document.getElementById('btnBellNotify');
      if (btn) btn.disabled = true;

      try {
        const res = await fetch('/api/youtube/subscribe', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ videoId: v.id, channelHandle: v.channelHandle })
        });
        const data = await res.json();
        if (data.ok) {
          v.isSubscribed = data.isSubscribed;
          ytSubscribedMap[v.channelHandle] = data.isSubscribed;
          if (typeof data.subscribersCount === 'number') {
            v.channelSubscribers = data.subscribersCount;
            v.channelSubscribersText = data.subscribersText || (data.subscribersCount.toLocaleString() + ' subscribers');
          }
          if (btn) {
            btn.innerText = data.isSubscribed ? 'Subscribed ✓' : 'Subscribe';
            if (data.isSubscribed) btn.classList.add('subscribed');
            else btn.classList.remove('subscribed');
          }
          if (counter) {
            counter.innerText = v.channelSubscribersText;
          }
          if (bellBtn) {
            bellBtn.style.display = data.isSubscribed ? 'flex' : 'none';
          }
          showAccountToast(data.isSubscribed ? '🔔 Subscribed to ' + v.channelName : '🔕 Unsubscribed from ' + v.channelName);
        } else {
          showAccountToast('⚠️ ' + (data.error || 'Failed to update subscription'));
        }
      } catch (err) {
        console.error('Subscription error:', err);
      } finally {
        if (btn) btn.disabled = false;
      }
    }

    function cycleBellNotification() {
      bellNotificationIndex = (bellNotificationIndex + 1) % bellNotificationOptions.length;
      const setting = bellNotificationOptions[bellNotificationIndex];
      const icon = document.getElementById('bellIcon');
      if (icon) {
        if (setting === 'all') icon.innerText = '🔔';
        else if (setting === 'personalized') icon.innerText = '🔕';
        else icon.innerText = '🔕';
      }
      alert('Notification preference set to: ' + setting.toUpperCase());
    }

    function toggleYtDescription() {
      const descBox = document.getElementById('ytDescBox');
      const toggleBtn = document.getElementById('ytDescToggle');
      if (!descBox || !toggleBtn) return;
      const isCollapsed = descBox.classList.contains('collapsed');
      if (isCollapsed) {
        descBox.classList.remove('collapsed');
        toggleBtn.innerText = 'Show less';
      } else {
        descBox.classList.add('collapsed');
        toggleBtn.innerText = 'Show more';
      }
    }

    let currentPublicChannelData = null;

    async function openPublicChannelView(channelIdOrHandle) {
      const surface = document.getElementById('publicChannelSurface') || document.getElementById('channelProfileModal');
      if (surface) {
        surface.style.display = 'flex';
      }
      const v = (typeof ytVideosCatalog !== 'undefined' && ytVideosCatalog[activeYtVideoIndex]) ? ytVideosCatalog[activeYtVideoIndex] : null;
      let handle = (channelIdOrHandle || (v ? v.channelHandle : 'sovralab') || 'sovralab').replace(/^@/, '');
      let chName = v ? v.channelName : 'Sovra Protocol Lab';
      let chAvatar = v ? v.channelAvatar : '🎬';
      let chAvatarBg = v ? v.channelAvatarBg : '#6366f1';

      try {
        const res = await fetch('/api/social/channels/get?handle=' + encodeURIComponent(handle));
        const data = await res.json();
        if (data && data.ok && data.channel) {
          currentPublicChannelData = data;
          const ch = data.channel;
          chName = ch.name || chName;
          chAvatar = ch.avatar || chAvatar;
          chAvatarBg = ch.avatarBg || chAvatarBg;
        }
      } catch (err) {}

      const avatarEl = document.getElementById('publicChannelAvatar') || document.getElementById('modalChannelAvatar');
      if (avatarEl) {
        avatarEl.innerText = chAvatar;
        avatarEl.style.background = chAvatarBg;
      }
      const nameEl = document.getElementById('publicChannelName') || document.getElementById('modalChannelName');
      if (nameEl) nameEl.innerText = chName;

      const subEl = document.getElementById('publicChannelSubscribers') || document.getElementById('modalChannelSubscribers');
      if (subEl) {
        const count = (v && v.channelSubscribersText) ? v.channelSubscribersText : '142.8K subscribers';
        subEl.innerHTML = '@' + handle + ' &bull; ' + count + ' &bull; 4 videos';
      }
      const hText = document.getElementById('publicChannelHandleText');
      if (hText) hText.innerText = '@' + handle;
      const scText = document.getElementById('publicChannelSubCountText');
      if (scText) scText.innerText = (v && v.channelSubscribersText) ? v.channelSubscribersText : '142.8K subscribers';

      switchPublicChannelTab('videos');
    }
    window.openPublicChannelView = openPublicChannelView;

