      handle: 'pioneer',
      displayName: 'Sovereign Pioneer',
      emoji: '🚀',
      ringGradient: 'linear-gradient(45deg, #f09433, #e6683c, #dc2743, #cc2366, #bc1888)',
      did: 'did:sovra:e25519_pioneer_8f92a10b',
      isHandleAvailable: true,
      faucetClaimed: false
