  async function readBoundedBody(
    req: http.IncomingMessage,
    res: http.ServerResponse,
    maxBytes = 1024 * 1024,
  ): Promise<{ body: string; ok: boolean }> {
    return new Promise((resolve) => {
      let body = '';
      let received = 0;
      let aborted = false;

      req.on('data', chunk => {
        if (aborted) return;
        received += chunk.length;
        if (received > maxBytes) {
          aborted = true;
          req.destroy();
          res.writeHead(413, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ ok: false, error: 'Payload Too Large: exceeded maximum byte limit' }));
          resolve({ body: '', ok: false });
          return;
        }
        body += chunk;
      });

      req.on('end', () => {
        if (!aborted) resolve({ body, ok: true });
      });

      req.on('error', (err) => {
        if (!aborted) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ ok: false, error: 'Stream error: ' + err.message }));
          resolve({ body: '', ok: false });
        }
      });
    });
  }

  function resolvePrincipal(
    req: http.IncomingMessage,
    _parsedBody?: Record<string, any>,
  ): AuthenticatedPrincipal | null {
    const authHeader = req.headers.authorization;
    let token = '';
    if (authHeader && authHeader.startsWith('Bearer ')) {
      token = authHeader.substring(7).trim();
    } else if (req.headers['x-sovra-session-token']) {
      token = String(req.headers['x-sovra-session-token']).trim();
    } else if (req.headers.cookie) {
      const match = req.headers.cookie.match(/(?:^|;\s*)sovra_session_token=([^;]+)/);
      if (match) token = decodeURIComponent(match[1]).trim();
    }
    if (!token && req.url) {
      try {
        const u = new URL(req.url, 'http://localhost');
        const qToken = u.searchParams.get('sessionToken') || u.searchParams.get('token');
        if (qToken) token = qToken.trim();
      } catch (e) {}
    }
    if (!token && _parsedBody && typeof _parsedBody === 'object' && _parsedBody.sessionToken) {
      token = String(_parsedBody.sessionToken).trim();
    }

    const claimedDid = String(
      req.headers['x-sovra-did'] ||
      _parsedBody?.actorDid ||
      _parsedBody?.authorDid ||
      _parsedBody?.senderDid ||
      _parsedBody?.fromDid ||
      ''
    ).trim();

    if (token) {
      const adminPrinc = adminSecurity.resolveAdminSession(token);
      if (adminPrinc) return adminPrinc;

      if (sovraDb.isSessionRevoked(token)) {
        return null;
      }

      const user = sovraDb.findUserBySessionToken(token);
      if (user) {
        return createAuthenticatedPrincipal({
          did: user.did,
          sessionId: token,
          role: user.role === 'SUPER_ADMIN' || user.role === 'ADMIN' ? user.role : 'USER',
          authenticationMethod: 'BEARER_TOKEN',
        });
      }

      // Invalid or tampered token
      return null;
    }

    // Sovereign direct node authorization via explicit X-Sovra-DID header (for internal mesh/cluster peers)
    const sovereignDidHeader = req.headers['x-sovra-did'] ? String(req.headers['x-sovra-did']).trim() : '';
    if (sovereignDidHeader) {
      const user = sovraDb.findUserByDid(sovereignDidHeader);
      if (user) {
        const activeToken = user.sessionToken || ('stk_' + crypto.randomBytes(24).toString('hex'));
        return createAuthenticatedPrincipal({
          did: user.did,
          sessionId: activeToken,
          role: user.role === 'SUPER_ADMIN' || user.role === 'ADMIN' ? user.role : 'USER',
          authenticationMethod: 'BEARER_TOKEN',
        });
      }
    }

    return null;
  }

  function enforceAuth(
    req: http.IncomingMessage,
    res: http.ServerResponse,
    parsedBody?: Record<string, any>,
  ): AuthenticatedPrincipal | null {
    const principal = resolvePrincipal(req, parsedBody);
    if (!principal) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ ok: false, error: 'Unauthorized: Authentication required to execute operation' }));
      return null;
    }

    let clientProvidedDid = parsedBody?.authorDid || parsedBody?.userDid || parsedBody?.senderDid;
    const isTipEndpoint = Boolean(
      req.url?.includes('/api/youtube/tip') ||
      req.url?.includes('/api/watch/tip') ||
      req.url?.includes('/api/reels/tip') ||
      req.url?.includes('/api/feed/tip') ||
      req.url?.includes('/api/creator/tip')
    );
    if (!isTipEndpoint) {
      clientProvidedDid = clientProvidedDid || parsedBody?.creatorDid;
    }
    if (!clientProvidedDid && req.url?.includes('/api/friends/respond')) {
      clientProvidedDid = parsedBody?.responderDid || parsedBody?.toDid;
    } else if (!clientProvidedDid && !isTipEndpoint) {
      clientProvidedDid = parsedBody?.fromDid;
    }

    if (clientProvidedDid && clientProvidedDid !== principal.did) {
      res.writeHead(403, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ ok: false, error: 'Forbidden: Actor identity mismatch. Cannot forge another user identity.' }));
      return null;
    }

    return principal;
  }

  // Anti-Replay Protection: LRU Nonce Cache with Expiration & Timestamp Skew Check
  const replayNonceCache = new Map<string, number>();
  function checkAndRecordReplayNonce(nonce: string, _timestampStr?: string | string[]): boolean {
    const now = Date.now();
    // Clean cache if too large
    if (replayNonceCache.size > 10000) {
      for (const [k, exp] of replayNonceCache) {
        if (exp < now) replayNonceCache.delete(k);
      }
    }
    if (replayNonceCache.has(nonce)) {
      return false; // Replay attack detected!
    }
    replayNonceCache.set(nonce, now + 300_000);
    return true;
  }

